#!/usr/bin/env python3
"""Bridge 总控脚本（主流程唯一总控入口）。

采用 argparse 子命令路由，清晰隔离 7 大总控职责：
  1. 服务生命周期管控（start / stop / status / rotate）：
     python src/scripts/bridge.py start [--fg]
     python src/scripts/bridge.py stop [--force]
     python src/scripts/bridge.py status
     python src/scripts/bridge.py rotate

  2. 单端直接调度（run）：
     python src/scripts/bridge.py run <chatgpt|gemini|grok|deepseek|codex|dsh|opencode|workbuddy> [choose|use] [参数...]

  3. 多端派单与轮询取证（ask）：
     python src/scripts/bridge.py ask --endpoints codex,workbuddy --prompt "问题" --purpose test

  4. 自迭代十步循环总控（iterate）：
     python src/scripts/bridge.py iterate status --round round-0
     python src/scripts/bridge.py iterate review --round round-0 --site chatgpt
     python src/scripts/bridge.py iterate verify --round round-0

  5. 工作流状态机（workflow）：
     python src/scripts/bridge.py workflow status --file progress.json

  6. 任务卡完工通知（notify）与 WorkBuddy 自动续推（autopush）：
     python src/scripts/bridge.py notify --card 01 --status done --note "说明"
     python src/scripts/bridge.py autopush [--dry-run] [--idle-minutes 10]

  7. 本地诊断工具箱快捷入口（tools，调用本地保留的 tools/*.py 诊断脚本）：
     python src/scripts/bridge.py tools --list
     python src/scripts/bridge.py tools verify_all
"""
from __future__ import annotations

import argparse
import inspect
import subprocess
import sys
import types
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SRC = ROOT / "src"
if str(SRC) not in sys.path:
    sys.path.insert(0, str(SRC))

_SUBMODULES_SRC: dict[str, str] = {
    "bridge_server": '"""本地后端 server 的生命周期命令（CARD-09a）。\n\n用法（在 F:\\\\Bridge\\\\v0.0.9 下）：\n\n    py -3.10 src\\\\scripts\\\\bridge_server.py start              # 后台起，等 /health 通了才返回\n    py -3.10 src\\\\scripts\\\\bridge_server.py start --foreground  # 前台跑，Ctrl+C 结束\n    py -3.10 src\\\\scripts\\\\bridge_server.py stop [--force]\n    py -3.10 src\\\\scripts\\\\bridge_server.py status\n    py -3.10 src\\\\scripts\\\\bridge_server.py rotate             # 换 token（服务要重启才生效）\n\n约定：\n- 只绑 127.0.0.1，端口取 docs\\\\bridge_server.json（默认 18765）。\n- 端口被占 / 已有实例在跑 → 打印 JSON 错误并退 1，不抢占、不改端口。\n- token 只写进 `%LOCALAPPDATA%\\\\Bridge\\\\v009\\\\server.json`，**不打印**；\n  start / status / rotate 只回 token 文件路径和打码后的样子。\n- 子进程的 stdout/stderr 写到 `runs\\\\server.log`（只有启动/错误行，不含 token）。\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport http.client\nimport json\nimport os\nimport socket\nimport subprocess\nimport sys\nimport time\nfrom pathlib import Path\n\n_SRC = Path(__file__).resolve().parents[1]\nif str(_SRC) not in sys.path:\n    sys.path.insert(0, str(_SRC))\n\nfrom qi import console, server, uilock  # noqa: E402\n\nROOT = server.ROOT\nLOG_PATH = ROOT / "runs" / "server.log"\nSTART_WAIT = 10.0\nSTOP_WAIT = 5.0\n\n\ndef _emit(payload: dict, code: int = 0) -> int:\n    print(json.dumps(payload, ensure_ascii=False))\n    return code\n\n\ndef _env() -> dict:\n    env = dict(os.environ)\n    existing = env.get("PYTHONPATH") or ""\n    env["PYTHONPATH"] = str(_SRC) + (os.pathsep + existing if existing else "")\n    return env\n\n\n#: 让子进程**不继承父控制台**：父 shell 退出时不会给它发 CTRL_CLOSE_EVENT。\n#: 2026-11-08（B14）：这是"start 起的后端随父 shell 一起死"的根因修复。\nDETACHED_PROCESS = 0x00000008\n#: 允许子进程脱离父进程所在的 job 对象（否则 job 关闭会连带杀掉它）。\n#: 只在父 job 允许 breakaway 时才成功，否则 CreateProcess 直接 ERROR_ACCESS_DENIED。\nCREATE_BREAKAWAY_FROM_JOB = 0x01000000\nERROR_ACCESS_DENIED = 5\n\n\ndef _creationflags(*, breakaway: bool = True) -> int:\n    """后台子进程的创建标志（纯函数，便于直接断言整数）。\n\n    **不再带 `CREATE_NO_WINDOW` / `CREATE_NEW_PROCESS_GROUP`**：\n    前者与 `DETACHED_PROCESS` 同时使用时会被系统忽略，留着只会让人误以为\n    "已经做了隔离"；后者只影响 Ctrl+C 的分发组，对 `taskkill /T` 无效。\n    """\n    if os.name != "nt":\n        return 0\n    flags = DETACHED_PROCESS\n    if breakaway:\n        flags |= CREATE_BREAKAWAY_FROM_JOB\n    return flags\n\n\ndef _spawn_detached(argv: list[str], handle) -> tuple[subprocess.Popen, str]:\n    """起一个脱离当前 shell 的常驻子进程，返回 (child, how)。\n\n    先试带 `CREATE_BREAKAWAY_FROM_JOB`；父 job 不允许脱离时系统会拒绝\n    （`ERROR_ACCESS_DENIED`），此时**降级**为仅 `DETACHED_PROCESS` 重试一次。\n    其它 `OSError` 原样抛出，仍走调用方的 `spawn_failed` 分支。\n    """\n\n    def _launch(breakaway: bool) -> subprocess.Popen:\n        return subprocess.Popen(\n            list(argv), cwd=str(ROOT), env=_env(), stdin=subprocess.DEVNULL,\n            stdout=handle, stderr=handle,\n            creationflags=_creationflags(breakaway=breakaway))\n\n    try:\n        return _launch(True), "breakaway"\n    except OSError as exc:\n        if getattr(exc, "winerror", None) != ERROR_ACCESS_DENIED:\n            raise\n        return _launch(False), "plain"\n\n\ndef _health(port: int, timeout: float = 1.0) -> tuple[bool, dict | None, str]:\n    conn = None\n    try:\n        conn = http.client.HTTPConnection(server.HOST, int(port), timeout=timeout)\n        conn.request("GET", "/health")\n        response = conn.getresponse()\n        raw = response.read()\n        try:\n            data = json.loads(raw.decode("utf-8"))\n        except (UnicodeDecodeError, ValueError):\n            data = None\n        return response.status == 200, data, ""\n    except (OSError, http.client.HTTPException) as exc:\n        return False, None, f"{type(exc).__name__}: {exc}"\n    finally:\n        if conn is not None:\n            conn.close()\n\n\ndef _post(path: str, payload: dict, *, port: int, token: str,\n          timeout: float = 3.0) -> tuple[int | None, dict | None, str]:\n    conn = None\n    try:\n        conn = http.client.HTTPConnection(server.HOST, int(port), timeout=timeout)\n        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")\n        headers = {"Content-Type": "application/json", "Authorization": f"Bearer {token}"}\n        conn.request("POST", path, body=body, headers=headers)\n        response = conn.getresponse()\n        raw = response.read()\n        try:\n            data = json.loads(raw.decode("utf-8"))\n        except (UnicodeDecodeError, ValueError):\n            data = None\n        return response.status, data, ""\n    except (OSError, http.client.HTTPException) as exc:\n        return None, None, f"{type(exc).__name__}: {exc}"\n    finally:\n        if conn is not None:\n            conn.close()\n\n\ndef _port_free(port: int) -> tuple[bool, str]:\n    """先探一下端口；Windows 上用 SO_EXCLUSIVEADDRUSE，和真绑定一样严格。"""\n    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)\n    try:\n        exclusive = getattr(socket, "SO_EXCLUSIVEADDRUSE", None)\n        if exclusive is not None:\n            sock.setsockopt(socket.SOL_SOCKET, exclusive, 1)\n        sock.bind((server.HOST, int(port)))\n        return True, ""\n    except OSError as exc:\n        return False, str(exc)\n    finally:\n        sock.close()\n\n\ndef _state() -> dict:\n    return {\n        "token_file": str(server.state_path()),\n        "pid_file": str(server.pid_path()),\n    }\n\n\n# ---------------------------------------------------------------- start\ndef start(port: int | None = None, *, foreground: bool = False) -> int:\n    config = server.load_config()\n    listen = int(port or config["port"])\n\n    info = server.read_pid()\n    if info and uilock.pid_alive(info.get("pid")):\n        ok, health, _ = _health(int(info.get("port") or listen))\n        return _emit({"ok": False, "action": "start", "error": "already_running",\n                      "pid": info.get("pid"), "port": info.get("port"),\n                      "health_ok": ok, "health": health, **_state()}, 1)\n    if info:\n        server.clear_pid()                       # 上次留下的死 pid，清掉\n\n    free, detail = _port_free(listen)\n    if not free:\n        return _emit({"ok": False, "action": "start", "error": "port_in_use",\n                      "port": listen, "detail": detail, **_state()}, 1)\n\n    if foreground:\n        try:\n            return server.serve(listen)\n        except OSError as exc:\n            return _emit({"ok": False, "action": "start", "error": "bind_failed",\n                          "port": listen, "detail": str(exc), **_state()}, 1)\n\n    LOG_PATH.parent.mkdir(parents=True, exist_ok=True)\n    handle = open(LOG_PATH, "a", encoding="utf-8")\n    detached = "plain"\n    try:\n        child, detached = _spawn_detached(\n            [sys.executable, "-m", "qi.server", "--serve", "--port", str(listen)],\n            handle)\n    except OSError as exc:\n        handle.close()\n        return _emit({"ok": False, "action": "start", "error": "spawn_failed",\n                      "port": listen, "detail": str(exc), **_state()}, 1)\n    handle.close()\n\n    deadline = time.monotonic() + START_WAIT\n    health = None\n    while time.monotonic() < deadline:\n        ok, data, error = _health(listen, 0.5)\n        if ok:\n            health = data\n            break\n        if child.poll() is not None:\n            break\n        time.sleep(0.1)\n\n    if health is None:\n        server.terminate_tree(child)\n        return _emit({"ok": False, "action": "start", "error": "start_failed",\n                      "port": listen, "pid": child.pid, "log": str(LOG_PATH),\n                      "detail": "server did not answer /health in %.0fs" % START_WAIT,\n                      **_state()}, 1)\n\n    return _emit({"ok": True, "action": "start", "port": health.get("port", listen),\n                  # `/health` 只回 {ok, version} 是公开契约，**不许**加 pid；\n                  # 所以 pid 只能取自 child（原来写 health.get("pid") 恒为 null）。\n                  "pid": child.pid, "detached": detached,\n                  "health": health, "token": "***", "log": str(LOG_PATH), **_state()})\n\n\n# ---------------------------------------------------------------- stop\ndef stop(*, force: bool = False) -> int:\n    info = server.read_pid()\n    if not info:\n        ok, _, _ = _health(server.load_config()["port"])\n        if not ok:\n            return _emit({"ok": True, "action": "stop", "running": False,\n                          "note": "not running"})\n        return _emit({"ok": False, "action": "stop", "error": "pid_file_missing",\n                      "detail": "server answers /health but no server.pid; pass --force "\n                                "only after locating the process yourself"}, 1)\n\n    listen = int(info.get("port") or server.load_config()["port"])\n    pid = int(info["pid"])\n    ok, health, error = _health(listen)\n    if not ok and uilock.pid_alive(pid) is False:\n        server.clear_pid(pid)\n        return _emit({"ok": True, "action": "stop", "running": False,\n                      "note": "process already exited; stale pid file removed", "pid": pid})\n\n    state = server.load_state()\n    if state:\n        status, body, error = _post("/shutdown", {}, port=listen, token=state["token"])\n        if status == 200:\n            deadline = time.monotonic() + STOP_WAIT\n            while time.monotonic() < deadline:\n                if uilock.pid_alive(pid) is False:\n                    break\n                time.sleep(0.1)\n            server.clear_pid(pid)\n            return _emit({"ok": True, "action": "stop", "running": False,\n                          "pid": pid, "graceful": True})\n        if status == 409 and not force:\n            return _emit({"ok": False, "action": "stop", "error": "job_running",\n                          "pid": pid, "detail": (body or {}).get("message"),\n                          "hint": "wait for the job, or stop --force (kills the process tree)"}, 1)\n        detail = error or (body or {}).get("message") or f"HTTP {status}"\n    else:\n        detail = f"token state missing: {server.state_path()}"\n\n    if not force:\n        return _emit({"ok": False, "action": "stop", "error": "shutdown_failed",\n                      "pid": pid, "detail": detail, "hint": "retry with --force"}, 1)\n\n    server.terminate_tree(pid)\n    deadline = time.monotonic() + STOP_WAIT\n    while time.monotonic() < deadline:\n        if uilock.pid_alive(pid) is False:\n            break\n        time.sleep(0.1)\n    server.clear_pid(pid)\n    return _emit({"ok": True, "action": "stop", "running": False, "pid": pid,\n                  "graceful": False, "note": "terminated process tree"})\n\n\n# ---------------------------------------------------------------- status\ndef status() -> int:\n    info = server.read_pid()\n    listen = int((info or {}).get("port") or server.load_config()["port"])\n    ok, health, error = _health(listen)\n    running = bool(ok and health)\n    pid = (info or {}).get("pid")\n    # pid_alive 返回 True/False/None。**None 不等于活着**（问不动就是没证据）。\n    alive = uilock.pid_alive(pid) if pid else None\n    payload = {"ok": running, "action": "status", "running": running,\n               "port": listen, "pid": pid, "pid_alive": alive,\n               # pid 文件在、但里面那个进程已经没了：下次 start 会自己清掉\n               "stale_pid_file": bool(pid) and alive is not True,\n               # 端口上有人应答，但应答的不是 pid 文件里那个进程\n               # （最常见：另一份 checkout 的后端占着同一个端口）\n               "mismatch": bool(running and alive is not True),\n               "health": health, "token": "***", **_state()}\n    if not running and error:\n        payload["detail"] = error\n    return _emit(payload, 0 if running else 1)\n\n\n# ---------------------------------------------------------------- rotate\ndef rotate() -> int:\n    config = server.load_config()\n    state = server.load_state()\n    if state is None:\n        state = server.load_or_create_state(port=int(config["port"]))\n    else:\n        state = server.rotate_token()\n    info = server.read_pid()\n    running = bool(info and uilock.pid_alive(info.get("pid")))\n    return _emit({"ok": True, "action": "rotate", "rotated": True,\n                  "token": server.mask_token(state.get("token")),\n                  "restart_required": running,\n                  "note": "read the new token from the token file; restart the server"\n                          if running else "read the new token from the token file",\n                  **_state()})\n\n\ndef main(argv: list[str] | None = None) -> int:\n    parser = argparse.ArgumentParser(prog="bridge_server.py",\n                                     description="Bridge local server lifecycle")\n    sub = parser.add_subparsers(dest="action", required=True)\n\n    p_start = sub.add_parser("start")\n    p_start.add_argument("--port", type=int, default=None)\n    p_start.add_argument("--foreground", action="store_true")\n\n    p_stop = sub.add_parser("stop")\n    p_stop.add_argument("--force", action="store_true")\n\n    sub.add_parser("status")\n    sub.add_parser("rotate")\n\n    args = parser.parse_args(argv)\n    if args.action == "start":\n        return start(args.port, foreground=args.foreground)\n    if args.action == "stop":\n        return stop(force=args.force)\n    if args.action == "status":\n        return status()\n    if args.action == "rotate":\n        return rotate()\n    parser.print_help()\n    return 2\n\n\nif __name__ == "__main__":\n    console.setup()\n    raise SystemExit(main())\n',
    "workflow_use": '"""工作流状态机命令行（任务卡 05，第 5 项后端部分）。\n\n用法（--file 必填，没有默认值，免得手滑写到真 progress.json）：\n\n    python src\\\\scripts\\\\workflow_use.py status        --file progress.json\n    python src\\\\scripts\\\\workflow_use.py move 05 done  --file progress.json\n    python src\\\\scripts\\\\workflow_use.py move 05 hold  --file progress.json --missing 截图 --missing 退出码\n    python src\\\\scripts\\\\workflow_use.py advance 05    --file progress.json\n    python src\\\\scripts\\\\workflow_use.py resolve-hold 05 --file progress.json\n\n--workflow 可选，默认按 qi/workflow.py 往上推到项目根再拼 docs\\\\workflow\\\\workflow.json。\n\n退出码：\n    0  正常\n    2  被规则拒绝（非法跳转、hold 没带清单、证据没补齐就出 hold、卡不在 hold）\n    3  advance 后需要监工（同时多打一行 ``需要监工: <卡号>``）\n    4  其他错误（文件不存在、JSON 坏、卡号不存在、状态名不存在、参数不对）\n\n只读写 --file 指到的那一个文件；不开窗口、不发消息、不调用任何端的 CLI。\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport sys\nfrom pathlib import Path\n\n_SRC = Path(__file__).resolve().parents[1]\nif str(_SRC) not in sys.path:\n    sys.path.insert(0, str(_SRC))\n\nfrom qi import console, workflow  # noqa: E402\n\nEXIT_OK = 0\nEXIT_REJECTED = 2\nEXIT_NEED_SUPERVISOR = 3\nEXIT_ERROR = 4\n\n\nclass UsageError(Exception):\n    """参数写错：交给 main 统一打成退出码 4，别用 argparse 默认的 2。"""\n\n\nclass _Parser(argparse.ArgumentParser):\n    def error(self, message: str):        # noqa: D401 - argparse 的钩子\n        raise UsageError(message)\n\n\ndef build_parser() -> argparse.ArgumentParser:\n    common = _Parser(add_help=False)\n    common.add_argument("--file", default=argparse.SUPPRESS,\n                        help="progress 文件路径（必填，测试用临时副本）")\n    common.add_argument("--workflow", default=argparse.SUPPRESS,\n                        help="workflow.json 路径（可选，默认 docs\\\\workflow\\\\workflow.json）")\n\n    parser = _Parser(prog="workflow_use.py", parents=[common],\n                     description="Bridge 工作流状态机（只读写 --file 指定的文件）")\n    subs = parser.add_subparsers(dest="command", metavar="{status,move,advance,resolve-hold}")\n    subs.required = True\n\n    subs.add_parser("status", parents=[common], help="打印每张卡及状态")\n    move_parser = subs.add_parser("move", parents=[common], help="按跳转表改一张卡的状态")\n    move_parser.add_argument("card", help="卡号，如 05")\n    move_parser.add_argument("state", help="目标状态，如 done")\n    move_parser.add_argument("--missing", action="append", metavar="项",\n                             help="进 hold 时缺的证据，可重复")\n    advance_parser = subs.add_parser("advance", parents=[common], help="监工推一次")\n    advance_parser.add_argument("card", help="卡号，如 05")\n    hold_parser = subs.add_parser("resolve-hold", parents=[common], help="补齐证据后回 verifying")\n    hold_parser.add_argument("card", help="卡号，如 05")\n    return parser\n\n\ndef _print_rows(rows: list[dict]) -> None:\n    if not rows:\n        print("(没有卡)")\n        return\n    for row in rows:\n        line = f"{row[\'card\']} {row[\'state\']}"\n        if row.get("parent"):\n            line += f" parent={row[\'parent\']}"\n        if row.get("missing"):\n            line += f" missing={len(row[\'missing\'])}"\n        print(line)\n\n\ndef main(argv: list[str] | None = None) -> int:\n    try:\n        args = build_parser().parse_args(argv)\n    except UsageError as exc:\n        print(f"参数错误: {exc}", file=sys.stderr)\n        return EXIT_ERROR\n\n    file_arg = getattr(args, "file", None)\n    if not file_arg:\n        print("参数错误: 缺少 --file <progress 路径>（没有默认值）", file=sys.stderr)\n        return EXIT_ERROR\n    workflow_arg = getattr(args, "workflow", None)\n\n    try:\n        if args.command == "status":\n            _print_rows(workflow.summary(progress_path=file_arg))\n            return EXIT_OK\n\n        if args.command == "move":\n            result = workflow.move(args.card, args.state, missing=args.missing,\n                                   progress_path=file_arg, workflow_path=workflow_arg)\n            print(f"{result[\'card\']} {result[\'from\']} -> {result[\'to\']}")\n            if result.get("repair_card"):\n                print(f"修复卡: {result[\'repair_card\']} (parent={result[\'card\']})")\n            return EXIT_OK\n\n        if args.command == "advance":\n            result = workflow.advance(args.card, progress_path=file_arg,\n                                      workflow_path=workflow_arg)\n            if result["need_supervisor"]:\n                print(f"需要监工: {str(args.card).strip()}")\n                return EXIT_NEED_SUPERVISOR\n            return EXIT_OK\n\n        if args.command == "resolve-hold":\n            result = workflow.resolve_hold(args.card, progress_path=file_arg,\n                                           workflow_path=workflow_arg)\n            print(f"{result[\'card\']} {result[\'from\']} -> {result[\'to\']}")\n            return EXIT_OK\n    except workflow.MoveRejected as exc:\n        print(str(exc), file=sys.stderr)\n        return EXIT_REJECTED\n    except workflow.WorkflowError as exc:\n        print(f"错误: {exc}", file=sys.stderr)\n        return EXIT_ERROR\n    except OSError as exc:\n        print(f"错误: 读写失败 ({exc})", file=sys.stderr)\n        return EXIT_ERROR\n\n    print(f"参数错误: 未知子命令 {args.command}", file=sys.stderr)\n    return EXIT_ERROR\n\n\nif __name__ == "__main__":\n    console.setup()          # 入口编码：GBK 控制台不再被 \\u200b 打崩（CARD-08 第 1 条）\n    raise SystemExit(main())\n',
    "notify_done": '"""写完 progress.json，再发一条完工通知（任务卡 01）。\n\n用法：\n    python src\\\\scripts\\\\notify_done.py --card 01 --status done --note "一句话说明"\n\n环境变量：\n    BRIDGE_NOTIFY_URL  收通知的地址。没设就只写文件：不联网、不报错、退出码 0。\n    BRIDGE_NOTIFY_KEY  有就放进请求头 X-Bridge-Key；不落盘、不进日志、不写进 progress.json。\n\n顺序固定：先落文件，再发通知——通知失败也不能让监工看不到状态。\nPOST 的 body 和 progress.json 内容一致，Content-Type: application/json; charset=utf-8。\n地址是 127.0.0.1 / localhost 时直连、不走 HTTP_PROXY（代理接不了回环）。\n发送失败重试 2 次（共 3 次尝试），仍失败就在 progress.json 记 notify_failed=true，\n退出码仍为 0；只有「写文件」本身失败才返回 2。\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport os\nimport sys\nimport time\nimport urllib.parse\nimport urllib.request\nfrom pathlib import Path\n\n_SRC = Path(__file__).resolve().parents[1]\nif str(_SRC) not in sys.path:\n    sys.path.insert(0, str(_SRC))\n\nfrom qi import progress  # noqa: E402\n\nTIMEOUT = 5.0       # 单次 POST 超时（秒）\nRETRIES = 2         # 失败后重试次数：共 3 次尝试\nRETRY_WAIT = 0.5    # 重试间隔基数，第 n 次重试等 n * RETRY_WAIT\nUSER_AGENT = "bridge-notify/0.0.9"\nLOOPBACK = {"127.0.0.1", "localhost", "::1"}\n\n\ndef _open(request: urllib.request.Request, timeout: float):\n    """回环地址直连：本机若设了 HTTP_PROXY，代理也接不了 127.0.0.1。"""\n    host = (urllib.parse.urlsplit(request.full_url).hostname or "").lower()\n    if host in LOOPBACK:\n        opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))\n        return opener.open(request, timeout=timeout)\n    return urllib.request.urlopen(request, timeout=timeout)\n\n\ndef post(url: str, key: str, payload: dict, *, timeout: float = TIMEOUT,\n         retries: int = RETRIES, wait: float | None = None) -> tuple[bool, str]:\n    """发一次通知，失败重试。返回 (成功与否, 最后一次的错误描述)。"""\n    wait = RETRY_WAIT if wait is None else wait\n    body = json.dumps(payload, ensure_ascii=False).encode("utf-8")\n    headers = {"Content-Type": "application/json; charset=utf-8", "User-Agent": USER_AGENT}\n    if key:\n        headers["X-Bridge-Key"] = key\n    last = ""\n    for attempt in range(retries + 1):\n        try:\n            request = urllib.request.Request(url, data=body, headers=headers, method="POST")\n            with _open(request, timeout) as response:\n                code = int(getattr(response, "status", None) or response.getcode())\n            if 200 <= code < 300:\n                return True, ""\n            last = f"HTTP {code}"\n        except Exception as exc:                      # noqa: BLE001 - 网络异常种类太多\n            last = f"{type(exc).__name__}: {exc}"\n        if attempt < retries and wait:\n            time.sleep(wait * (attempt + 1))\n    return False, last\n\n\ndef main(argv: list[str] | None = None) -> int:\n    parser = argparse.ArgumentParser(prog="notify_done.py", description="先写 progress.json，再发完工通知")\n    parser.add_argument("--card", required=True, help="任务卡号，如 01")\n    parser.add_argument("--status", required=True, choices=progress.STATUSES)\n    parser.add_argument("--note", required=True, help="一句话说明，不要粘提示词或回复正文")\n    args = parser.parse_args(argv)\n\n    try:\n        record = progress.write(args.card, args.status, args.note)\n    except (OSError, ValueError) as exc:\n        print(f"progress write failed: {exc}", file=sys.stderr)\n        return 2\n\n    url = os.environ.get("BRIDGE_NOTIFY_URL", "").strip()\n    if not url:\n        # T4-1 第 3 条：通知模块"未配置"必须明确登记，不能只是个静默 skip。\n        # 保留原有的人类可读行（有脚本/习惯依赖），再追加一行结构化状态供检索。\n        print(f"progress.json written ({record[\'status\']}); "\n              f"notify NOT_CONFIGURED (BRIDGE_NOTIFY_URL unset, notify skipped)")\n        print(json.dumps({"notify": "NOT_CONFIGURED",\n                          "reason": "BRIDGE_NOTIFY_URL_unset",\n                          "card": record.get("card_id"),\n                          "status": record.get("status")}, ensure_ascii=False))\n        return 0\n\n    key = os.environ.get("BRIDGE_NOTIFY_KEY", "").strip()\n    ok, error = post(url, key, record)\n    if ok:\n        print("progress.json written; notified")\n        return 0\n\n    try:                                    # 记不上失败标记也别改退出码\n        progress.mark_notify_failed(record)\n    except OSError:\n        pass\n    print(f"progress.json written; notify failed after {RETRIES + 1} attempts ({error})", file=sys.stderr)\n    return 0\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n',
    "workbuddy_autopush": '"""自动推：WorkBuddy 停了就补一句「继续按卡施工」（CARD-08 第 2 条 / PLAN 第 7 项子卡 CARD-07b）。\n\n判定和记账在 `qi/autopush.py`，这里只管命令行和「真去发」。\n\n用法：\n\n    python src\\\\scripts\\\\workbuddy_autopush.py --dry-run          只判定：不发消息、不写日志、不通知\n    python src\\\\scripts\\\\workbuddy_autopush.py                    判定该推就真发\n    python src\\\\scripts\\\\workbuddy_autopush.py --idle-minutes 10 --dry-run\n\n判定（`qi.autopush.decide`）：\n\n    progress.json 是 running\n    + runlog 超过 N 分钟没有新行（N 默认 20，`--idle-minutes` 可配；autopush 自己写的行不算）\n    + 没有「生成中」标志（runlog 最后一行的 `stage=generating`，或命令行 `--generating`）\n    → 推一次 `workbuddy_use --continue "继续按卡施工"`\n\n防重复：\n\n    同一张卡 30 分钟内最多推 1 次（`--cooldown-minutes`）；\n    连推 3 次 `progress.json` 的 `updated_at` 还没动过 → 停推，调用通知脚本叫红莉栖\n    （`--no-notify` 只用来验流程，同一个 progress 只叫一次）。\n\n真推成功后会在 `runs\\\\YYYYMMDD.jsonl` 记一行 `result=autopush_push`；推失败记\n`autopush_push_failed`（**不算**一次推，30 分钟冷却也不占用——没发出去就没打搅过谁）。\n\n退出码：\n\n    0  判定跑完：推成功 / 该等 / 不用动\n    1  该推，但 `workbuddy_use` 没成功（它的退出码和最后一行输出记在 runlog 的 error 里）\n    2  参数错\n    3  连推 3 次没有进展：已停推并叫过人（同一张卡同一次 progress 只叫一次）\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport os\nimport subprocess\nimport sys\nfrom pathlib import Path\n\n_SRC = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nif _SRC not in sys.path:\n    sys.path.insert(0, _SRC)\n\nfrom qi import autopush, console, progress, server, tier_guard, uilock  # noqa: E402\n\nSCRIPTS = Path(__file__).resolve().parent\nEXIT_OK = 0\nEXIT_PUSH_FAILED = 1\nEXIT_USAGE = 2\nEXIT_NEEDS_HUMAN = 3\nPUSH_TIMEOUT = 900          # workbuddy_use 自身 --timeout 之外的总闸（秒）\n\n\ndef run_command(cmd: list[str], *, timeout: float = PUSH_TIMEOUT) -> tuple[int, str, str]:\n    # Shares the active parent UI transaction through the verified 09a protocol.\n    result = server.run_process(cmd, timeout=timeout, cwd=SCRIPTS.parent.parent)\n    return (result.get("exit_code") if result.get("exit_code") is not None else 127,\n            result.get("stdout") or "", result.get("stderr") or "")\n\n\ndef _last_line(text: str) -> str:\n    rows = [row for row in (text or "").splitlines() if row.strip()]\n    return rows[-1] if rows else ""\n\n\ndef push_command(prompt: str, *, purpose: str, timeout: float) -> list[str]:\n    """真去发的那条命令：`workbuddy_use --continue <一句话>`。"""\n    return [sys.executable, str(SCRIPTS / "workbuddy.py"), "use", prompt,\n            "--continue", "--purpose", purpose, "--timeout", str(timeout)]\n\n\ndef notify_command(card: str, note: str) -> list[str]:\n    """叫人的那条命令：通知脚本自己会先写 progress.json 再发消息。"""\n    return [sys.executable, str(SCRIPTS / "bridge.py"), "notify",\n            "--card", card, "--status", "stuck", "--note", note]\n\n\ndef build_parser() -> argparse.ArgumentParser:\n    parser = argparse.ArgumentParser(\n        prog="workbuddy_autopush.py",\n        description="WorkBuddy 停了就推一句「继续按卡施工」（判定默认 20 分钟、同卡 30 分钟 1 次）")\n    parser.add_argument("--dry-run", action="store_true", help="只判定：不发消息、不写日志、不通知")\n    parser.add_argument("--progress", default=str(progress.path()),\n                        help="progress.json 的完整路径（默认项目根\\\\progress.json）")\n    parser.add_argument("--runs", default=str(autopush.RUNS),\n                        help="运行日志目录（默认项目根\\\\runs）")\n    parser.add_argument("--idle-minutes", type=float, default=autopush.Config.idle_minutes,\n                        help="多久没新行算停了（默认 20 分钟）")\n    parser.add_argument("--cooldown-minutes", type=float, default=autopush.Config.cooldown_minutes,\n                        help="同一张卡最短推送间隔（默认 30 分钟）")\n    parser.add_argument("--max-pushes", type=int, default=autopush.Config.max_pushes,\n                        help="连推几次没进展就停（默认 3）")\n    parser.add_argument("--prompt", default=autopush.PROMPT, help="推过去的那句话")\n    parser.add_argument("--generating", action="store_true",\n                        help="「生成中」标志（workbuddy_use --list 判定出来的）")\n    parser.add_argument("--purpose", default="review", choices=list(tier_guard.PURPOSES),\n                        help="推过去时用的档位用途（默认 review=最高档，见 docs\\\\tiers.json）")\n    parser.add_argument("--timeout", type=float, default=180, help="workbuddy_use 的等待秒数")\n    parser.add_argument("--no-notify", action="store_true", help="停推时不叫红莉栖（只验流程）")\n    parser.add_argument("--now", help="把「现在」固定成这个时刻（复现用，ISO 8601）")\n    return parser\n\n\ndef _main(argv: list[str] | None = None, *, runner=run_command, now=None) -> int:\n    args = build_parser().parse_args(argv)\n    config = autopush.Config(idle_minutes=args.idle_minutes,\n                             cooldown_minutes=args.cooldown_minutes,\n                             max_pushes=args.max_pushes, prompt=args.prompt)\n    moment = autopush.parse_time(args.now) if args.now else now\n    moment = autopush._aware(moment, default=autopush.now_beijing())\n\n    record = autopush.read_progress(args.progress)\n    events = autopush.read_events(args.runs)\n    decision = autopush.decide(record, events, now=moment, config=config,\n                               generating=args.generating,\n                               fallback_time=autopush.modified_at(args.progress))\n    out = {"ok": True, "dry_run": bool(args.dry_run), **decision.as_dict(),\n           "status": record.get("status"), "progress_updated_at": record.get("updated_at"),\n           "idle_threshold_minutes": config.idle_minutes,\n           "cooldown_minutes": config.cooldown_minutes,\n           "max_pushes": config.max_pushes, "prompt": config.prompt}\n    if decision.should_push:\n        out["would_run"] = " ".join(push_command(config.prompt, purpose=args.purpose,\n                                                 timeout=args.timeout)[1:])\n\n    if decision.action in ("skip", "wait") or args.dry_run:\n        print(json.dumps(out, ensure_ascii=False))\n        return EXIT_OK\n\n    if decision.needs_human:\n        mark = autopush.progress_mark(record)\n        already = autopush.stop_notified(events, decision.card, mark)\n        out.update({"needs_human": True, "notified": False, "already_notified": already})\n        if already or args.no_notify:\n            print(json.dumps(out, ensure_ascii=False))\n            return EXIT_NEEDS_HUMAN\n        note = (f"自动推连续 {config.max_pushes} 次没有进展，已停推，请红莉栖看："\n                f"卡 {decision.card}（progress 仍 running）")\n        code, stdout, stderr = runner(notify_command(decision.card, note))\n        out.update({"notified": code == 0, "notify_exit": code,\n                    "notify_error": None if code == 0 else (_last_line(stderr) or _last_line(stdout)) or f"EXIT={code}"})\n        autopush.append(autopush.event_for(decision, record, result=autopush.STOP,\n                                           ok=code == 0, error=out["notify_error"],\n                                           prompt=config.prompt), root=args.runs)\n        print(json.dumps(out, ensure_ascii=False))\n        return EXIT_NEEDS_HUMAN\n\n    # Decide/count is serialized by main; UI choose and use share one hold.\n    code, stdout, stderr = _push_with_receipt(args, config.prompt, record, runner)\n    payload = server.parse_last_json(stdout) or {}\n    already = payload.get("stage") == "already_answered" and payload.get("ok") is True\n    pushed = not already and (payload.get("submission") == "accepted" or payload.get("sent") is True)\n    ok = code == 0 and payload.get("ok") is True\n    error = None if ok else ((_last_line(stderr) or _last_line(stdout)) or f"EXIT={code}")\n    result = (autopush.PUSH if pushed else "autopush_already_answered" if already else autopush.PUSH_FAILED)\n    autopush.append(autopush.event_for(decision, record, result=result, ok=ok,\n                                     error=error, prompt=config.prompt), root=args.runs)\n    out.update({"ok": ok, "pushed": pushed, "already_answered": already,\n                "push_exit": code, "push_error": error,\n                "push_reply": _last_line(stdout) if ok else None})\n    print(json.dumps(out, ensure_ascii=False))\n    return EXIT_OK if ok else EXIT_PUSH_FAILED\n\n\ndef _push_with_receipt(args, prompt, record, runner):\n    app_root = SCRIPTS.parent.parent\n    try:\n        with uilock.hold("autopush:workbuddy", root=app_root):\n            current = autopush.read_progress(args.progress)\n            if any(current.get(key) != record.get(key) for key in ("card_id", "status", "updated_at")):\n                return 5, "", "progress_changed"\n            tiers = tier_guard.load_tiers(app_root / "docs/tiers.json")\n            allowed = tier_guard.allowed_tiers("workbuddy", args.purpose, "model", tiers=tiers)\n            if not allowed:\n                return 5, "", "table_unconfigured: WorkBuddy purpose has no verified tier"\n            before = tier_guard.read_receipt("workbuddy", root=app_root)\n            choose = [sys.executable, str(SCRIPTS / "workbuddy.py"), "choose", "--model", allowed[0]]\n            code, stdout, stderr = runner(choose, timeout=120)\n            if code:\n                return code, stdout, stderr\n            after = tier_guard.read_receipt("workbuddy", root=app_root)\n            if not after or (before and after.get("created_monotonic") == before.get("created_monotonic")):\n                return 5, "", "choose produced no fresh receipt"\n            verdict = tier_guard.check("workbuddy", args.purpose, root=app_root, tiers=tiers)\n            if not verdict["ok"]:\n                return 5, "", "choose receipt rejected: " + ",".join(verdict["reasons"])\n            current = autopush.read_progress(args.progress)\n            if any(current.get(key) != record.get(key) for key in ("card_id", "status", "updated_at")):\n                return 5, "", "progress_changed"\n            reply_timeout = tier_guard.floor_timeout(args.purpose, args.timeout)\n            return runner(push_command(prompt, purpose=args.purpose, timeout=reply_timeout),\n                          timeout=reply_timeout + 30)\n    except (uilock.Busy, tier_guard.TierUnconfirmed, OSError, ValueError) as exc:\n        return getattr(exc, "code", 5), "", f"{type(exc).__name__}: {exc}"\n\n\ndef main(argv: list[str] | None = None, *, runner=run_command, now=None) -> int:\n    args = build_parser().parse_args(argv)\n    if args.dry_run:\n        return _main(argv, runner=runner, now=now)\n    # Re-read decision and append count inside one cross-process transaction.\n    with tier_guard.file_lock(Path(args.runs) / "autopush.lock", timeout=PUSH_TIMEOUT + 180):\n        return _main(argv, runner=runner, now=now)\n\n\nif __name__ == "__main__":\n    console.setup()\n    raise SystemExit(main())\n',
    "live_job": '"""真机驱动：提交一个 /ask job，轮询到终态，落证据。\n\n**为什么单独成文件**：2026-11-08 之前两次真机尝试都是内联 `urllib` 片段，\n失败时没留下任何可复现的东西（`evidence/batch13/live_*.txt` 全文只有\n`ConnectionRefusedError`）。真机验证必须能一条命令重放。\n\n平台约束：\n- 只连 `127.0.0.1`，token 从 `%LOCALAPPDATA%\\\\Bridge\\\\v009\\\\server.json` 读，**不打印**。\n- **必须绕过系统代理**：本机开着代理，`urllib` 默认走它，本机回环会拿到 502。\n- 退出码：0=全部 done；1=partial；2=failed；3=等待超时。\n\n用法：\n  py -3.10 -X utf8 -B tools/live_job.py --endpoints codex,workbuddy \\\n      --prompt "只回复：XXX" --purpose test --out evidence/batch14/job_p2.json\n"""\nimport argparse\nimport json\nimport os\nimport pathlib\nimport sys\nimport time\nimport urllib.error\nimport urllib.request\nimport uuid\n\nBASE = "http://127.0.0.1:18765"\n\n\ndef token_of() -> str:\n    path = pathlib.Path(os.environ["LOCALAPPDATA"]) / "Bridge" / "v009" / "server.json"\n    return json.loads(path.read_text(encoding="utf-8"))["token"]\n\n\ndef make_caller(token: str):\n    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))\n\n    def call(path: str, body=None):\n        data = json.dumps(body).encode("utf-8") if body is not None else None\n        request = urllib.request.Request(\n            BASE + path, data=data,\n            # 服务端只认 `Authorization: Bearer <token>`（`server.py:_authorized`），\n            # 不是自定义头；写错会得到 401 unauthorized。\n            headers={"Content-Type": "application/json",\n                     "Authorization": f"Bearer {token}"},\n            method="POST" if body is not None else "GET")\n        with opener.open(request, timeout=30) as response:\n            return json.loads(response.read().decode("utf-8"))\n\n    return call\n\n\ndef brief(endpoint_row: dict) -> str:\n    name = endpoint_row.get("status")\n    use = endpoint_row.get("use") or {}\n    progress = endpoint_row.get("progress") or {}\n    parts = [str(name)]\n    if use.get("stage"):\n        parts.append(f"stage={use[\'stage\']}")\n    if progress.get("stage"):\n        secs = int(progress.get("elapsed") or 0)\n        parts.append(f"{progress[\'stage\']} {secs}s")\n        if progress.get("reads") is not None:\n            parts.append(f"读{progress[\'reads\']}")\n    return " ".join(parts)\n\n\ndef main(argv=None) -> int:\n    parser = argparse.ArgumentParser(prog="live_job.py")\n    parser.add_argument("--endpoints", required=True, help="逗号分隔，如 codex,workbuddy")\n    parser.add_argument("--prompt", help="提问正文（与 --prompt-file 二选一）")\n    parser.add_argument("--prompt-file", help="从文件读提问（多行长材料用；优先于 --prompt）")\n    parser.add_argument("--purpose", default="test")\n    parser.add_argument("--wait", type=float, default=180.0, help="最多等多少秒")\n    parser.add_argument("--interval", type=float, default=3.0)\n    parser.add_argument("--out", default="", help="把完整 job JSON 写到这里")\n    parser.add_argument("--label", default="", help="打印用的标记")\n    args = parser.parse_args(argv)\n\n    # B20：长材料（3–5k 字、几十行）经 shell 传参在引号/换行上不可靠，改从文件读。\n    if args.prompt_file:\n        prompt = pathlib.Path(args.prompt_file).read_text(encoding="utf-8")\n    elif args.prompt:\n        prompt = args.prompt\n    else:\n        parser.error("--prompt 与 --prompt-file 必须给一个")\n    args.prompt = prompt\n\n    names = [item.strip() for item in args.endpoints.split(",") if item.strip()]\n    call = make_caller(token_of())\n    label = f"[{args.label}] " if args.label else ""\n\n    print(f"{label}提交 {time.strftime(\'%H:%M:%S\')} → {names} purpose={args.purpose}",\n          flush=True)\n    submitted = call("/ask", {"endpoints": names, "prompt": args.prompt,\n                              "purpose": args.purpose, "request_id": str(uuid.uuid4())})\n    job_id = submitted["job_id"]\n    print(f"{label}job {job_id} status={submitted.get(\'status\')}", flush=True)\n\n    started = time.monotonic()\n    last_line = None\n    samples = []\n    job = {}\n    while time.monotonic() - started < args.wait:\n        job = call(f"/jobs/{job_id}")["job"]\n        rows = job.get("endpoints") or {}\n        line = f"{label}[{int(time.monotonic() - started):3d}s] {job[\'status\']:<8} " + \\\n               " | ".join(f"{name}: {brief(rows.get(name) or {})}" for name in names)\n        if line != last_line:\n            print(line, flush=True)\n            last_line = line\n        # B16：只采 reads 看不出「为什么一直不交卷」。把心跳里的诊断帧也留下来，\n        # 超时被 kill 时 stdout 会整个丢掉，只有这份采样能还原 text_len/busy 曲线。\n        trace_keys = ("stage", "reads", "busy", "copies", "baseline", "accepted",\n                      "composer_len", "text_len", "candidates", "sig", "why")\n        progress = {n: (rows.get(n) or {}).get("progress", {}) for n in names}\n        samples.append({\n            "at": round(time.monotonic() - started, 1), "status": job["status"],\n            "reads": {n: progress[n].get("reads") for n in names},\n            "trace": {n: {k: progress[n][k] for k in trace_keys if k in progress[n]}\n                      for n in names},\n        })\n        if job["status"] in ("done", "partial", "failed"):\n            break\n        time.sleep(args.interval)\n\n    print(f"\\n{label}=== 终态 ===")\n    print(f"{label}status={job.get(\'status\')} quorum={job.get(\'quorum\')}")\n    rows = job.get("endpoints") or {}\n    for name in names:\n        row = rows.get(name) or {}\n        use = row.get("use") or {}\n        print(f"{label}  {name}: status={row.get(\'status\')} stage={use.get(\'stage\')} "\n              f"elapsed={row.get(\'elapsed\')}")\n        print(f"{label}    detail={use.get(\'detail\')}")\n        print(f"{label}    choose={{{(row.get(\'choose\') or {}).get(\'dimension\')}: "\n              f"{(row.get(\'choose\') or {}).get(\'elapsed\')}s ok={(row.get(\'choose\') or {}).get(\'ok\')}}}")\n        print(f"{label}    reply={(row.get(\'reply\') or \'\')[:110]!r}")\n        err = row.get("error")\n        if err:\n            print(f"{label}    error={err}")\n\n    if args.out:\n        path = pathlib.Path(args.out)\n        path.parent.mkdir(parents=True, exist_ok=True)\n        path.write_text(json.dumps({"job": job, "samples": samples},\n                                   ensure_ascii=False, indent=2), encoding="utf-8")\n        print(f"{label}证据写入 {path}")\n\n    status = job.get("status")\n    if status == "done":\n        return 0\n    if status == "partial":\n        return 1\n    if status == "failed":\n        return 2\n    return 3\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n',
    "iterate": '"""自迭代循环的驱动器（规格 §4 的十步）。\n\n真机动作只在这里：发问、上传、读回复。判定、材料、匿名、验真全在\n`src/qi/iteration.py`（可离线测）。\n\n用法：\n    py -3.10 -B tools/iterate.py status --round round-0\n    py -3.10 -B tools/iterate.py snapshot --round round-0\n    py -3.10 -B tools/iterate.py review --round round-0 --site chatgpt\n    py -3.10 -B tools/iterate.py verify --round round-0\n    py -3.10 -B tools/iterate.py anonymize --round round-0\n    py -3.10 -B tools/iterate.py summarize --round round-0\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport re\nimport subprocess\nimport sys\nimport time\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\nsys.path.insert(0, str(ROOT / "src"))\n\nfrom qi import iteration as it                      # noqa: E402\n\nCONFIG_PATH = ROOT / "docs" / "iteration.json"\nDEFAULT_CONFIG = {\n    # 投喂方式：upload=网页端上传文件；paste=分段粘贴。按厂商分别设定。\n    "feed": {"chatgpt": "upload", "grok": "paste", "gemini": "paste", "deepseek": "paste"},\n    "chunk_chars": 3600,\n    "seats": ["chatgpt", "grok", "gemini", "deepseek"],\n    "review_timeout": 900,\n    "upload_timeout": 120,\n}\n\n\ndef load_config() -> dict:\n    cfg = dict(DEFAULT_CONFIG)\n    if CONFIG_PATH.is_file():\n        cfg.update(json.loads(CONFIG_PATH.read_text(encoding="utf-8")) or {})\n    return cfg\n\n\ndef _review_budget(cfg) -> int:\n    """会审等答案的预算：**必须**过一遍 `tier_guard.floor_timeout`。\n\n    规格 §7.1：`purpose=review` 走 `REVIEW_TIMEOUT` 下限，不得把高档会审判成\n    小超时。`*_use.py` 的 CLI 入口本来就会 floor，但 `iterate.py` 是直接调\n    `conversation.ask` / `subprocess.run`，绕过了那层 —— 2026-11-12 实测：\n    配置写 480，`conversation.ask` 就在 480s 收工（Round 4 chatgpt 582s 报 timeout\n    正落在这条线上），而同一份配置交给 `gemini_use.py` 时子进程自己抬到 1500，\n    **父进程 `timeout=budget+180` 反而先把子进程杀了**，答案就在页面上却收不回来。\n\n    所以这里统一取 floor 后的值，父进程的 subprocess 超时也基于它算。\n    """\n    from qi import tier_guard\n\n    try:\n        raw = float((cfg or {}).get("review_timeout") or DEFAULT_CONFIG["review_timeout"])\n    except (TypeError, ValueError):\n        raw = float(DEFAULT_CONFIG["review_timeout"])\n    return int(tier_guard.floor_timeout("review", raw))\n\n\ndef _run_or_timeout(cmd, timeout, what):\n    """跑子进程；超时返回 `(None, 结构化失败)`，不把 `TimeoutExpired` 抛出去。\n\n    为什么必须包：`subprocess.run(timeout=…)` 超时抛的是异常。原来的四处调用都没接，\n    于是子进程卡住时（UI 锁死、网页端不返回）整个 `review` / `summarize` 命令以\n    traceback 收场，**归档里一行结果都没有**，事后连"是超时还是崩了"都分不清。\n    和 `ask_failure` 同一个理由：失败也要留下可读的原因。\n    """\n    try:\n        return subprocess.run(cmd, cwd=ROOT, capture_output=True, text=True,\n                              encoding="utf-8", timeout=timeout), None\n    except subprocess.TimeoutExpired:\n        return None, {"ok": False, "stage": "timeout", "timeout_kind": "hard",\n                      "reason": "subprocess_timeout",\n                      "hint": f"{what}：子进程超过 {timeout}s 未退出，已强杀"}\n\n\ndef git(*args: str) -> str:\n    return subprocess.run(["git", *args], cwd=ROOT, capture_output=True,\n                          text=True, encoding="utf-8").stdout.strip()\n\n\ndef round_dir(name: str) -> Path:\n    return ROOT / "docs" / "iterations" / name\n\n\n# ---------------------------------------------------------------- 1. 快照\ndef cmd_snapshot(args, cfg) -> int:\n    state = it.State.load(ROOT, args.round)\n    sha = git("rev-parse", "HEAD")\n    branch = git("rev-parse", "--abbrev-ref", "HEAD")\n    remote = git("remote", "get-url", "origin")\n    snapshot = {"repo": remote, "branch": branch, "sha": sha,\n                "date": time.strftime("%Y-%m-%dT%H:%M:%S%z"),\n                "orchestrator": "tools/iterate.py@1"}\n    it.write_archive(round_dir(args.round), {"snapshot.json": snapshot})\n    state.set("snapshot", snapshot)\n    state.mark("snapshot", {"sha": sha})\n    print(json.dumps(snapshot, ensure_ascii=False))\n    return 0\n\n\n# ---------------------------------------------------------------- 2. 发问\ndef _screen_for(site: str, *, new: bool = False):\n    from qi.flow import ensure_site\n    from qi.screen import Screen\n\n    hwnd = ensure_site(site, tab=None, continue_session=not new, verbose=False)\n    screen = Screen(verbose=False)\n    screen.bind(hwnd)\n    if not screen.focus():\n        raise RuntimeError(f"{site}: 拿不到前台")\n    screen.tab_site = site\n    return screen\n\n\ndef _upload_settled(site: str, screen, timeout: float = 90.0) -> bool:\n    """等附件传完。\n\n    注意：**不能**等"发送键可用"——空输入框本来就不启用发送键，\n    那样会一直等到超时（Round 0 第一枪就是这么空等 20 分钟的）。\n    判据改成页面上不再出现「正在上传」。\n    """\n    from qi import ui\n\n    end = time.time() + timeout\n    while time.time() < end:\n        try:\n            control, _url = ui.document(screen.target_hwnd, site)\n            root = ui.tree(control)\n        except Exception:                     # noqa: BLE001\n            time.sleep(1.0)\n            continue\n        if not any("正在上传" in (node.name or "") for node in root.walk()):\n            return True\n        time.sleep(1.0)\n    return False\n\n\n#: 各端「新开会话」的入口名。取不到就退回站点根。\nNEW_CHAT = {\n    "chatgpt": ("新聊天", "新对话"),\n    "gemini": ("发起新对话",),\n    "grok": ("聊天",),\n    "deepseek": ("开启新对话", "新建对话"),\n}\nROOT_URL = {\n    "chatgpt": "https://chatgpt.com/",\n    "grok": "https://grok.com/",\n    "gemini": "https://gemini.google.com/app",\n    "deepseek": "https://chat.deepseek.com/",\n}\n\n\ndef conversation_session_id(url: str):\n    """从地址里取与标题无关的会话 id；没有就是新会话页。"""\n    from qi.conversation import session_id_of\n    return session_id_of(url)\n\n\ndef start_new_chat(screen, site: str, timeout: float = 20.0) -> bool:\n    """真的新开一个会话，并**验证 URL 已经变**。\n\n    上一轮的教训：`ensure_site(continue_session=False)` 并不会替 chatgpt 新开，\n    材料被贴进了旧会话，取回的"回复"是别的话题。发错地方的代价比不发大得多，\n    所以这里必须验证；验证不过就返回 False，调用方**不许发送**。\n    """\n    from qi import ui\n\n    def url_now() -> str:\n        try:\n            control, url = ui.document(screen.target_hwnd, site)\n            return url or ""\n        except Exception:                     # noqa: BLE001\n            return ""\n\n    before = url_now()\n    if before and conversation_session_id(before) is None:\n        return True                      # 已经在新会话页（例如站点根）\n    end = time.time() + timeout\n    while time.time() < end:\n        try:\n            control, _url = ui.document(screen.target_hwnd, site)\n            root = ui.tree(control)\n        except Exception:                     # noqa: BLE001\n            time.sleep(0.5)\n            continue\n        target = None\n        for node in root.walk():\n            if node.kind not in ("ButtonControl", "HyperlinkControl") or node.offscreen:\n                continue\n            name = (node.name or "").strip()\n            if name and any(name == want for want in NEW_CHAT.get(site, ())):\n                target = node\n                break\n        if target is not None:\n            rect = target.control.BoundingRectangle\n            screen.click_xy((rect.left + rect.right) // 2, (rect.top + rect.bottom) // 2)\n            time.sleep(2.0)\n            after = url_now()\n            if after and conversation_session_id(after) is None:\n                # 「新会话页」= 地址里没有会话 id。已经在 `/` 时点一下不会变地址，\n                # 那也算成功（再发一条自然就是新会话）。\n                return True\n        time.sleep(1.0)\n    return False\n\n\ndef _is_prompt_echo(block: str, prompt: str, squashed_prompt: str) -> bool:\n    """这一块是不是提问回声（整块落在提问里）。"""\n    squashed = "".join(block.split())\n    # 「可访问=是」是答案抬头，即使和提问重合也要留；\n    # 含「」/章节号/文件:行号 的块是**合规引文**，同样豁免（2026-11-12 会审：\n    # 按重合长度一刀切会把逐字引用删掉，验真直接归零）。\n    looks_like_citation = any(mark in block for mark in ("「", "」", "§")) \\\n        or re.search(r"[\\w./-]+\\.(?:py|md|json|yml|yaml):\\d+", block) is not None\n    return bool(len(squashed) >= 8 and not squashed.startswith("可访问")\n                and not looks_like_citation and squashed in squashed_prompt)\n\n\ndef _echo_head(blocks: list[str]) -> int:\n    """前序区到哪结束：第一条正式意见的行首。"""\n    for index, block in enumerate(blocks):\n        stripped = block.strip()\n        if (re.match(r"^\\s*(?:\\d+[）).、]|[①-⑥]|[A-E][\\s\u3000])", stripped)\n                or "章节号" in stripped[:12]):\n            return index\n    return 0\n\n\ndef _drop_prompt_echo(blocks: list[str], prompt: str) -> list[str]:\n    """剔掉与提问重合的块。\n\n    chatgpt 实测会在回答尾部把自己收到的提问复述 3 段（2026-11-12 Round 1），\n    如果留着，会被验真当成"引用"或拉低命中率。判据：整块是提问的连续子串。\n    """\n    squashed_prompt = "".join(prompt.split())\n    if not squashed_prompt:\n        return blocks\n    # 只在前序区剥（第一条正式意见之前）。正文里引用提问原句是合法的，\n    # 一旦进入意见区就停止剥离（2026-11-12 会审建议）。\n    head = _echo_head(blocks)\n    return [block for position, block in enumerate(blocks)\n            if (position >= head and head > 0)\n            or not _is_prompt_echo(block, prompt, squashed_prompt)]\n\n\ndef _rect_tuple(rect):\n    """UIA 矩形统一成 `(left, top, right, bottom)`；无效返回 None。"""\n    if rect is None:\n        return None\n    try:\n        left, top, right, bottom = rect.left, rect.top, rect.right, rect.bottom\n    except AttributeError:\n        try:\n            left, top, right, bottom = rect\n        except Exception:                     # noqa: BLE001\n            return None\n    if bottom <= top or right <= left:\n        return None\n    return (left, top, right, bottom)\n\n\ndef _join_by_lines(items) -> str:\n    """把同一视觉行的碎片拼回一行，跨行才换行。\n\n    为什么：chatgpt 的行内代码（`safe_ui.py` / `_ask_upload_body`）在控件树里是\n    **独立节点**，按节点换行会把一句「引用」拆成 3 行（2026-11-12 实测 Round 2：\n    5 处引句里 4 处被拆断，验真只认出 1 处，把一个引句齐全的回复判成 unread）。\n    这里按控件矩形回拼：垂直中心相差 ≤ 半行高、且水平相邻（间隔 ≤ 40px）的算同一行。\n    """\n    lines: list[dict] = []\n    for text, rect in items:\n        box = _rect_tuple(rect)\n        if box is None:\n            lines.append({"center": None, "parts": [text], "left": 0, "right": 0})\n            continue\n        left, top, right, bottom = box\n        center = (top + bottom) / 2\n        height = bottom - top\n        if lines:\n            last = lines[-1]\n            same_line = (\n                last["center"] is not None\n                and abs(last["center"] - center) <= max(4.0, height * 0.45)\n                and left - last["right"] <= 40\n            )\n            if same_line:\n                last["parts"].append(text)\n                last["left"] = min(last["left"], left)\n                last["right"] = max(last["right"], right)\n                continue\n        lines.append({"center": center, "parts": [text],\n                      "left": left, "right": right})\n    return "\\n".join("".join(line["parts"]) for line in lines).strip()\n\n\ndef _merged_blocks(texts):\n    """委托：实现只在 `qi.conversation.merged_blocks`（定位与取回共用一套规则）。"""\n    from qi import conversation\n\n    return conversation.merged_blocks(texts)\n\n\ndef _prompt_span(texts, needle: str, start_at: int = 0):\n    """委托：实现只在 `qi.conversation.prompt_span`。"""\n    from qi import conversation\n\n    return conversation.prompt_span(texts, needle, start_at=start_at)\n\n\ndef is_progress_noise(text: str) -> bool:\n    """端自己的过程行/品牌名，不是答案。\n\n    grok 会把「Analyzing the specification document」这类思考步骤和「工作了 57s」\n    一起挂进控件树（2026-11-12 实测 6 条），留着会被验真算成一条没有引句的意见。\n    """\n    probe = (text or "").strip()\n    if not probe:\n        return True\n    if probe in ("Grok", "ChatGPT", "DeepSeek", "Gemini") or probe.endswith("已完成回复"):\n        return True\n    if probe.startswith("工作了") and probe.endswith("s"):\n        return True\n    # 纯英文的进行时短句（首字母大写、无句末标点）——本项目的会审都用中文\n    if (probe.isascii() and probe[:1].isupper() and len(probe) < 80\n            and not probe.endswith((".", "。", "!", "?", ":", ";", "；"))):\n        return True\n    return False\n\n\ndef read_answer_text(screen, site: str, prompt: str) -> str:\n    """从控件树里按顺序读答案文本（复制键点不到时的兜底）。\n\n    两步，先准后广：\n\n    1. **锚在提问回声上**。树序常见形状是「侧栏标题 … 提问回声 … 答案 … 提问回声」，\n       取**第一个**回声之后、下一个回声（或「已完成回复」标记）之前的块。\n       grok 实测就是这样：0–6 是侧栏、7 是回声、8–49 是答案、50 是「Grok 已完成回复」、\n       51 又是回声。按关键字猜起点会把侧栏标题一起带进来。\n    2. 找不到回声时，退回按合同首行「可访问=…」找起点。\n    """\n    from qi import ui\n\n    squash = lambda x: "".join(x.split())          # noqa: E731\n    sp = squash(prompt)\n    key = sp[:36]\n    try:\n        control, _url = ui.document(screen.target_hwnd, site)\n        root = ui.tree(control)\n    except Exception:                     # noqa: BLE001\n        return ""\n\n    noise = {"回答已完成", "最新一条回复", "复制", "编辑", "朗读", "分享", "重新生成回复"}\n    done = re.compile(r"(已完成回复|回答已完成|已完成)$")\n    seen, blocks = set(), []\n    for node in root.walk():\n        if node.kind != "TextControl":\n            continue\n        text = (node.name or "").strip()\n        if not text or text in noise or is_progress_noise(text):\n            continue\n        # 输入框占位符会作为独立文本节点出现（grok「畅所欲问」、gemini「问问 Gemini」）\n        if text in SITE_PLACEHOLDERS.get(site, ()):  # noqa: F821 - 定义在本文件后段\n            continue\n        try:\n            rect = node.control.BoundingRectangle\n        except Exception:                 # noqa: BLE001 - 拿不到矩形就按独立行处理\n            rect = None\n        # **不能按长度丢**：chatgpt 把「」渲染成独立节点，一句引用的收尾就一个字符；\n        # 原来 `len(text) < 8` 把它丢了，于是每条引句都缺右括号、验真全判不中\n        # （2026-11-12 实测：5 条引句只有 1 条能配上对）。\n        # 去重也改成按「文本 + 位置」——单字符节点会重复出现多次。\n        dedupe_key = (text, getattr(rect, "top", None), getattr(rect, "left", None)) \\\n            if rect is not None else (text, None, None)\n        if dedupe_key in seen:\n            continue\n        seen.add(dedupe_key)\n        blocks.append((text, rect))\n\n    def is_echo(text: str) -> bool:\n        """这一块是不是提问（或提问的一段）。\n\n        grok 会把一条提问拆成 3 个 TextControl 渲染（2026-11-12 实测），\n        只认「整段包含前缀」会判成 prompt_gone；这里把「是提问的连续片段」\n        也算进来（≥12 字，短片段太容易撞上正文）。\n        """\n        squashed = squash(text)\n        if not squashed:\n            return False\n        if key and key in squashed:\n            return True\n        return len(squashed) >= 12 and squashed in sp\n\n    texts = [text for text, _rect in blocks]\n    # 提问可能被拆成多块，所以用**拼接后的整段**定位气泡起止：先找到它占的最后一块，\n    # 答案从下一块开始；再找一次同样的一段（grok 会在答案末尾再回显一遍）作为结束。\n    # 注意提问里的 markdown 强调（`**`）不会出现在渲染文本里，比较前先去掉。\n    stripped_prompt = sp.replace("*", "")\n    needle = stripped_prompt[:60]\n    first = next((i for i, t in enumerate(texts) if is_echo(t)), -1)\n\n    def collect(start_index: int, stop_index=None):\n        out = []\n        for index, (text, rect) in enumerate(blocks[start_index:], start=start_index):\n            if stop_index is not None and index >= stop_index:\n                break                       # 末尾那条回声 = 已经走过答案了\n            if stop_index is None and is_echo(text):\n                break\n            if done.search(text):\n                break\n            out.append((text, rect))\n        return out\n\n    if first >= 0:\n        body = collect(first + 1)\n        # 旧判据优先（多轮真机验证过）。只有它取到的正文短得不像答案时，才用\n        # 「拼接后定位气泡起止」——那条路能处理提问被拆成 9~10 块的情况，\n        # 但也更容易误锚到侧栏标题，所以不放在主路径上。\n        if len(_join_by_lines(body)) < 80:\n            # 用**能匹配上的最长前缀**定位气泡：前缀越短，落点越可能停在气泡中段\n            # （实测 60 字只覆盖到提问的第三块，答案会从半句提问开始）。\n            span = None\n            for size in (len(stripped_prompt), 200, 160, 120, 90, 60):\n                if size < 20:\n                    continue\n                candidate = stripped_prompt[:size]\n                span = _prompt_span(texts, candidate)\n                if span:\n                    needle = candidate\n                    break\n            if span:\n                stop = _prompt_span(texts, needle, start_at=span[2])\n                start_at = span[1] + 1\n                # 余下的提问碎片（`**`、`一句`…）继续跳过，直到出现不属于提问的块。\n                while start_at < len(blocks):\n                    probe = "".join(blocks[start_at][0].split()).replace("*", "")\n                    if len(probe) >= 2 and probe in stripped_prompt:\n                        start_at += 1\n                        continue\n                    break\n                alt = collect(start_at, stop[0] if stop else None)\n                if len(_join_by_lines(alt)) > len(_join_by_lines(body)):\n                    body = alt\n        if body:\n            # 与 `_drop_prompt_echo` 同一套规则：只在前序区剥回声，进入意见区就停。\n            head = _echo_head([t for t, _r in body])\n            out = []\n            for position, (text, rect) in enumerate(body):\n                if not (position >= head and head > 0) and _is_prompt_echo(text, prompt, sp):\n                    continue\n                if out and out[-1][0] == text:\n                    continue\n                out.append((text, rect))\n            return _join_by_lines(out)\n\n    # 退回：只认「可访问」开头的块（chatgpt 的答案就是这个形状）。\n    out, started = [], False\n    for text, rect in blocks:\n        if is_echo(text):\n            continue\n        if not started:\n            if text.startswith("可访问") or text.startswith("NO_ACCESS"):\n                started = True\n            else:\n                continue\n        out.append((text, rect))\n    kept = []\n    for text, rect in out:\n        if _is_prompt_echo(text, prompt, sp):\n            continue\n        if kept and kept[-1][0] == text:\n            continue\n        kept.append((text, rect))\n    return _join_by_lines(kept)\n\n\n#: 各端的输入框占位文字。`composer_empty` 的结构判据要求把它显式传进去，\n#: 否则空输入框会被当成草稿（gemini 实测：值就是「问问 Gemini」）。\nSITE_PLACEHOLDERS = {"gemini": ("问问 Gemini",), "grok": ("畅所欲问",)}\n\n\ndef _conversation(screen, site: str):\n    from qi import conversation\n\n    return conversation.Conversation(\n        screen, site,\n        empty=lambda view: conversation.composer_empty(\n            view, placeholders=SITE_PLACEHOLDERS.get(site, ())))\n\n\ndef _clear_composer(screen, site: str) -> bool:\n    """点输入框 → Ctrl+A → Delete 清空。\n\n    **必须把点击点夹进窗口矩形**：chatgpt 的编辑区 UIA 矩形会超出窗口下边界\n    （实测 402..1286，而窗口只到 780），点它的中心等于点在桌面上，\n    焦点立刻被桌面抢走，后面的按键全部 ForegroundLost。\n    """\n    from qi import ui\n    from qi.upload import _raw_click\n\n    try:\n        import uiautomation as auto\n\n        conv_ctl = auto.ControlFromHandle(screen.target_hwnd)\n        win = conv_ctl.BoundingRectangle\n        control, _url = ui.document(screen.target_hwnd, site)\n        root = ui.tree(control)\n        editors = [n for n in root.walk() if n.kind == "EditControl" and not n.offscreen]\n        if not editors:\n            return True\n        rect = editors[0].control.BoundingRectangle\n        # 取「控件矩形 ∩ 窗口矩形」的中心：\n        # · gemini 的输入框很小且在窗口内 —— 中心就是框里；\n        # · chatgpt 的编辑区会超出窗口下沿 —— 交集中心仍在窗口内。\n        left, right = max(rect.left, win.left), min(rect.right, win.right)\n        top, bottom = max(rect.top, win.top), min(rect.bottom, win.bottom)\n        if right - left < 8 or bottom - top < 8:\n            left, right, top, bottom = win.left, win.right, win.top, win.bottom\n        x = (left + right) // 2\n        y = (top + bottom) // 2\n        from qi import safe_ui\n\n        verdict = safe_ui.safe_click(screen.target_hwnd, x, y)\n        if not verdict.ok:\n            return False          # 点位不安全（桌面/他窗/客户区外）：一个键都不发\n        time.sleep(0.3)\n        # S1：发键前双检——前台是目标窗口 + 焦点在可编辑控件上；\n        # 2026-11-12 就是这样把 Ctrl+A/Delete 发到桌面、选中 155 个图标的。\n        import ctypes\n\n        import uiautomation as auto\n\n        try:\n            role = auto.GetFocusedControl().ControlTypeName\n        except Exception:                     # noqa: BLE001\n            role = None\n        key_verdict = safe_ui.decide_keys(\n            keys=("ctrl", "a"), foreground_hwnd=ctypes.windll.user32.GetForegroundWindow(),\n            target_hwnd=screen.target_hwnd, focused_role=role)\n        if not key_verdict.ok:\n            return False\n        screen.hotkey("ctrl", "a")\n        time.sleep(0.1)\n        screen.press("delete")\n        time.sleep(0.3)\n        return True\n    except Exception:                     # noqa: BLE001\n        return False\n\n\ndef harvest_reply(screen, site: str, wait: float = 420.0) -> dict:\n    """等「停止」消失、最后一条消息可复制且内容稳定，再复制回来。\n\n    为什么需要它：`conversation.ask` 只看动作条上的复制键数量，\n    chatgpt 在长回答**仍在生成**时复制键是 0，于是判超时；等它真生成完，\n    这里按「停止键消失 + 复制内容两次相同」收卷。\n    """\n    from qi import ui\n\n    def scroll_bottom(times: int = 6) -> None:\n        """把页面滚到底。动作条常在可见区之外（仓库文档记过 y≈2014 的坑），\n        不滚到底根本点不到复制键。"""\n        import ctypes\n\n        u32 = ctypes.windll.user32\n        u32.mouse_event(0x0800, 0, 0, -120 * times, 0)\n        time.sleep(0.6)\n\n    end = time.time() + wait\n    last_text, stable_since = "", None\n    while time.time() < end:\n        try:\n            control, _url = ui.document(screen.target_hwnd, site)\n            root = ui.tree(control)\n        except Exception:                 # noqa: BLE001\n            time.sleep(2.0)\n            continue\n        busy = any((n.name or "").strip() in ("停止", "Stop") for n in root.walk()\n                   if n.kind == "ButtonControl")\n        copies = [n for n in root.walk()\n                  if n.kind == "ButtonControl" and (n.name or "").strip() in ("复制", "Copy")]\n        if busy or not copies:\n            stable_since = None\n            time.sleep(2.0)\n            continue\n        scroll_bottom()\n        try:\n            control, _url = ui.document(screen.target_hwnd, site)\n            root = ui.tree(control)\n            copies = [n for n in root.walk()\n                      if n.kind == "ButtonControl"\n                      and (n.name or "").strip() in ("复制", "Copy")]\n        except Exception:                 # noqa: BLE001\n            time.sleep(2.0)\n            continue\n        if not copies:\n            time.sleep(2.0)\n            continue\n        rect = copies[-1].control.BoundingRectangle\n        seq_before = screen.clipboard_seq()\n        try:\n            screen.focus()            # 长等待里焦点可能掉到桌面，先抢回来\n            screen.click_xy((rect.left + rect.right) // 2, (rect.top + rect.bottom) // 2)\n        except Exception:             # noqa: BLE001 - 焦点抢不回来就用裸点击\n            __import__("qi.upload", fromlist=["x"])._raw_click(\n                (rect.left + rect.right) // 2, (rect.top + rect.bottom) // 2)\n        # **必须**等剪贴板序号变化：点空时读到的是用户自己的剪贴板内容\n        # （实测抓到过一段地址+电话），那不是回答。\n        for _ in range(20):\n            if screen.clipboard_seq() != seq_before:\n                break\n            time.sleep(0.15)\n        if screen.clipboard_seq() == seq_before:\n            time.sleep(2.0)\n            continue\n        text = screen.clipboard() or ""\n        if text and text == last_text:\n            return {"ok": True, "stage": "harvested", "reply": text}\n        last_text, stable_since = text, time.time()\n        time.sleep(3.0)\n    return {"ok": False, "stage": "harvest_timeout", "reply": last_text}\n\n\n#: 账本里这些状态意味着「可能已经发出去过」——只对账，不重发。\nRECONCILE_STATES = ("accepted", "submitting", "unknown")\n\n\ndef _ledger_state(site: str, prompt: str) -> str:\n    from qi import submissions\n\n    try:\n        return submissions.read_state(site, prompt) or "none"\n    except Exception:                     # noqa: BLE001 - 读不出账本按"未知"处理更安全\n        return "unknown"\n\n\ndef _page_has(screen, site: str, needle: str) -> bool:\n    """页面上有没有这段文字（续跑时核对"上一段到底发出去没有"）。"""\n    from qi import ui\n\n    try:\n        control, _url = ui.document(screen.target_hwnd, site)\n        root = ui.tree(control)\n    except Exception:                     # noqa: BLE001\n        return False\n    return any(needle in (node.name or "") for node in root.walk())\n\n\ndef _reconcile_gate(screen, site: str, ask_text: str) -> dict | None:\n    """发之前的账本闸门：有记录就只对账，不重发。\n\n    返回 None 表示可以发；返回 dict 表示接管本次结果。\n    `accepted/submitting/unknown` 一律先只读查答：\n      · 页面已有答案 → 直接采用（不重发）；\n      · 页面没有答案 → `needs_manual_clear`，交人工确认后清账本，**绝不自动清、不重发**。\n    """\n    state = _ledger_state(site, ask_text)\n    if state not in RECONCILE_STATES:\n        return None\n    text = read_answer_text(screen, site, ask_text)\n    if len(text) >= 300:\n        return {"ok": True, "stage": "already_answered", "reply": text,\n                "feed": "reconcile", "ledger": state}\n    return {"ok": False, "stage": "needs_manual_clear", "ledger": state,\n            "hint": "账本里已有该提问的提交记录，但页面找不到答案；按「只对账不重发」停手。"\n                    "人工核对后用 tools/submission_clear.py --file <记录> --state "\n                    f"{state} --reason ... --confirm 清掉再跑"}\n\n\ndef _url_now(screen, site: str) -> str:\n    from qi import ui\n\n    try:\n        _control, url = ui.document(screen.target_hwnd, site)\n        return url or ""\n    except Exception:                     # noqa: BLE001\n        return ""\n\n\ndef _navigate(screen, url: str, wait: float = 3.0) -> bool:\n    """把当前标签导航到 `url` 并确认地址真的变了。"""\n    if not url:\n        return False\n    try:\n        screen.hotkey("ctrl", "l")\n        time.sleep(0.3)\n        screen.type_text(url)\n        time.sleep(0.2)\n        screen.press("enter")\n        time.sleep(wait)\n    except Exception:                     # noqa: BLE001 - 前台被抢等\n        return False\n    return _url_now(screen, getattr(screen, "tab_site", "")) .split("?")[0] == url.split("?")[0]\n\n\ndef _session_plan(screen, site: str, state=None) -> dict:\n    """S3：按锚点决定 stay / navigate / new_allowed / session_lost。"""\n    from qi import session_anchor as sa\n\n    anchor = None\n    if state is not None:\n        raw = (state.data.get("anchors") or {}).get(site)\n        if raw:\n            anchor = sa.SessionAnchor.from_dict(raw)\n    decision = sa.resolve(anchor, _url_now(screen, site))\n    if decision["action"] == "navigate":\n        decision["ok"] = _navigate(screen, decision["url"])\n        if not decision["ok"] and anchor is not None and anchor.accepted:\n            return {"action": "session_lost", "url": decision["url"],\n                    "reason": "navigate_failed_after_accepted"}\n    return decision\n\n\ndef _remember_anchor(state, site: str, round_name: str, prompt_hash: str,\n                    accepted: bool) -> None:\n    """发送成功后把本轮会话钉住（下次续跑不再新开）。"""\n    from qi import session_anchor as sa\n\n    if state is None:\n        return\n    url = _url_now(_screen_for(site), site)\n    if not url:\n        return\n    anchors = state.data.setdefault("anchors", {})\n    anchors[site] = sa.SessionAnchor(site=site, round_name=round_name, url=url,\n                                     prompt_hash=prompt_hash,\n                                     accepted=bool(accepted)).to_dict()\n    state.save()\n\n\ndef _clear_stale_lock(state=None) -> dict:\n    """开跑前清掉「持有者已死」的残留锁，并把结果记进 state。\n\n    只改写**确认已死**的元数据；活着的锁一律不动（真并发时这里只会返回 held/alive）。\n    """\n    from qi import uilock\n\n    info = uilock.clear_stale()\n    if state is not None:\n        state.set("lock", {"checked_at": time.strftime("%Y-%m-%dT%H:%M:%S%z"),\n                           **{k: info.get(k) for k in ("cleared", "reason", "pid", "owner")}})\n    return info\n\n\ndef _ask_upload(site: str, prompt: str, material: Path, cfg, state=None,\n                force_new: bool = False) -> dict:\n    """上传 + 短提问。**整段持 UI 锁**：这段时间全是网页端动作。\n\n    离线步骤（验真、匿名、归档）一律不取锁——锁只在"要动网页"的时候存在。\n    """\n    from qi import uilock\n\n    with uilock.hold(f"iterate:upload:{site}",\n                     timeout=float(cfg.get("ui_lock_timeout", 180))):\n        return _ask_upload_body(site, prompt, material, cfg, state, force_new)\n\n\ndef _ask_upload_body(site: str, prompt: str, material: Path, cfg, state=None,\n                     force_new: bool = False) -> dict:\n    from qi import conversation, upload\n\n    screen = _screen_for(site)\n    _clear_composer(screen, site)\n    # S3：先看锚点再决定要不要新开。漂移就回跳；已 accepted 还漂移就硬停，绝不新建。\n    # 汇总必须**每次**新开对话：同一个会话里既有原意见又有汇总，匿名就白做了。\n    # 锚点机制是为"续跑同一次会审"设计的，不能用在汇总上（2026-11-12 实测：\n    # 第二次汇总复用了第一次的会话，session_id 完全没变）。\n    plan = ({"action": "new_allowed", "url": ""} if force_new\n            else _session_plan(screen, site, state))\n    if plan["action"] == "session_lost":\n        return {"ok": False, "stage": "session_lost", "feed": "upload",\n                "hint": "锚点漂移且已 accepted；按 §10 不新建、不重发，保留账本"}\n    if plan["action"] == "new_allowed":\n        if not start_new_chat(screen, site):\n            return {"ok": False, "stage": "new_chat_failed", "feed": "upload"}\n    elif plan["action"] == "navigate" and not plan.get("ok"):\n        return {"ok": False, "stage": "session_navigate_failed", "feed": "upload",\n                "hint": "锚点回跳失败，且未 accepted；未发送"}\n    up = upload.upload(screen, site, str(material), timeout=cfg["upload_timeout"])\n    if not up.ok:\n        return {"ok": False, "stage": "upload_failed", **up.as_dict()}\n    if not _upload_settled(site, screen):\n        return {"ok": False, "stage": "upload_not_settled", "upload": up.as_dict()}\n    # 上传模式材料在附件里，提问用一句短指令即可：长多行提问在部分端会写不进去。\n    # 每端可覆盖提问：deepseek 看到 `docs/...` 会去仓库找，然后回 NO_ACCESS\n    # （2026-11-12 实测），所以给它一条明确「只读附件」的提问。\n    ask_text = str((cfg.get("upload_prompt_by_site") or {}).get(site)\n                   or cfg.get("upload_prompt") or prompt)\n    # 账本优先：已有 accepted/submitting/unknown 就先只读对账，**不重发**。\n    gated = _reconcile_gate(screen, site, ask_text)\n    if gated is not None:\n        gated["upload"] = up.as_dict()\n        return gated\n    prompt_id = it.prompt_identity(site, getattr(state, "round_dir", None) and state.round_dir.name or "",\n                                   ask_text)\n    if state is not None:\n        state.mark_chunk(prompt_id, "sending")     # 发送**之前**落盘，崩溃后不留空白\n    _refresh_tier(site)                  # 回执一次性；上一次失败也会把它用掉\n    conv = _conversation(screen, site)\n    result = conversation.ask(conv, ask_text, timeout=_review_budget(cfg),\n                              purpose="review")\n    if state is not None:\n        state.mark_chunk(prompt_id, "sent" if result.get("ok") else "unknown",\n                         chars=len(result.get("reply") or ""))\n    _remember_anchor(state, site, getattr(state, "round_dir", None) and state.round_dir.name or "",\n                     prompt_id, accepted=bool(result.get("ok")\n                                              or result.get("submission") == "accepted"))\n    if not result.get("ok") and result.get("stage") in ("timeout", "interrupted", "harvest_timeout"):\n        # 兜底会**覆盖** result：把 ask 的失败细节先留一份，否则事后完全看不出\n        # 为什么这一席要走兜底（Round 3 的 grok 就是这样丢掉了 timeout_kind）。\n        failure = {key: result.get(key) for key in\n                   ("stage", "timeout_kind", "reason", "diagnostics", "warnings")\n                   if result.get(key) is not None}\n        harvested = harvest_reply(screen, site, wait=float(cfg.get("harvest_wait", 420)))\n        if harvested["ok"]:\n            result = {**harvested, "ask_failure": failure}\n        else:\n            # 复制键点不到时，直接从控件树读（答案确实在，只是动作条不可点）。\n            text = read_answer_text(screen, site, ask_text)\n            if len(text) >= 300:\n                result = {"ok": True, "stage": "text_extracted", "reply": text,\n                          "ask_failure": failure}\n    result["feed"] = "upload"\n    result["upload"] = up.as_dict()\n    return result\n\n\ndef _ask_upload_script(site: str, prompt: str, material: Path, cfg, state=None) -> dict:\n    """上传附件，再用该端自己的 `*_use.py` 写短指令并发送。\n\n    为什么不用 `conversation.ask`：gemini 在 upload 模式下会把「写了字、根本没\n    发出去」判成 accepted（2026-11-12 两次实测：账本 accepted，但地址仍是 `/app`、\n    输入框里还留着提问、0 个消息块），随后永远被 `submission_pending` 拦住。\n    各端 `*_use.py` 自带落点校验（`submit_not_landed`）与收卷逻辑，更可靠。\n    """\n    from qi import upload\n\n    screen = _screen_for(site)\n    _clear_composer(screen, site)\n    if not start_new_chat(screen, site):\n        return {"ok": False, "stage": "new_chat_failed", "feed": "upload-script"}\n    from qi import uilock\n\n    # 只包上传这一段：后面的 `*_use.py` 是子进程，它自己会 uilock.run，\n    # 父进程若也持锁就直接自锁死（2026-11-12 设计时排除）。\n    with uilock.hold(f"iterate:upload:{site}",\n                     timeout=float(cfg.get("ui_lock_timeout", 180))):\n        up = upload.upload(screen, site, str(material), timeout=cfg["upload_timeout"])\n        settled = _upload_settled(site, screen)\n    if not up.ok:\n        return {"ok": False, "stage": "upload_failed", "feed": "upload-script",\n                **up.as_dict()}\n    if not settled:\n        return {"ok": False, "stage": "upload_not_settled", "feed": "upload-script",\n                "upload": up.as_dict()}\n\n    ask_text = str((cfg.get("upload_prompt_by_site") or {}).get(site)\n                   or cfg.get("upload_prompt") or prompt)\n    gated = _reconcile_gate(screen, site, ask_text)   # 账本优先，只对账不重发\n    if gated is not None:\n        gated["upload"] = up.as_dict()\n        return gated\n    prompt_id = it.prompt_identity(site, getattr(state, "round_dir", None) and state.round_dir.name or "",\n                                   ask_text)\n    if state is not None:\n        state.mark_chunk(prompt_id, "sending")\n    _refresh_tier(site)                  # 回执一次性，发送前重拿一条\n    script = ROOT / "src" / "scripts" / f"{site}.py"\n    budget = _review_budget(cfg)\n    proc, timeout_err = _run_or_timeout(\n        [sys.executable, str(script), "use", ask_text, "--purpose", "review",\n         "--continue", "--timeout", str(budget)],\n        budget + 180, f"{site} 会审")\n    if timeout_err:\n        return {**timeout_err, "feed": "upload-script", "upload": up.as_dict()}\n    parsed = None\n    for line in reversed((proc.stdout or "").splitlines()):\n        line = line.strip()\n        if line.startswith("{") and line.endswith("}"):\n            try:\n                parsed = json.loads(line)\n                break\n            except ValueError:\n                continue\n    result = dict(parsed or {"ok": False, "stage": "bad_output",\n                             "exit": proc.returncode})\n    if state is not None:\n        state.mark_chunk(prompt_id, "sent" if result.get("ok") else "unknown",\n                         chars=len(result.get("reply") or ""))\n    result["feed"] = "upload-script"\n    result["upload"] = up.as_dict()\n    if not result.get("ok") and result.get("stage") in ("timeout", "interrupted"):\n        text = read_answer_text(screen, site, ask_text)\n        if len(text) >= 300:\n            result = {"ok": True, "stage": "text_extracted", "reply": text,\n                      "feed": "upload-script", "upload": up.as_dict()}\n    return result\n\n\ndef _site_object(name: str):\n    """复用各端 `*_use.py` 里打磨过的 Site 配置（新会话、输入框、发送键）。"""\n    import importlib.util\n\n    path = ROOT / "src" / "scripts" / f"{name}.py"\n    spec = importlib.util.spec_from_file_location(f"{name}_use_mod", path)\n    module = importlib.util.module_from_spec(spec)\n    spec.loader.exec_module(module)\n    return module.SITE\n\n\ndef _choose_tier(site: str, purpose: str = "review") -> dict:\n    """跑该端的 `*_choose.py` 选档位。\n\n    `purpose=review` 需要档位回执，否则 `conversation.ask` 直接 `tier_unconfirmed`\n    （deepseek 实测）。这一步本来就是会审流程的一部分。\n    """\n    import subprocess\n\n    script = ROOT / "src" / "scripts" / f"{site}.py"\n    if not script.is_file():\n        return {"ok": False, "reason": "no_choose_script"}\n    proc, timeout_err = _run_or_timeout(\n        [sys.executable, str(script), "choose", "--purpose", purpose], 180, f"{site} 选档")\n    if timeout_err:\n        return {"ok": False, "exit": None, "reason": "timeout",\n                "hint": timeout_err["hint"]}\n    return {"ok": proc.returncode == 0, "exit": proc.returncode,\n            "tail": (proc.stdout or "")[-200:]}\n\n\n#: 各端 review 档位回执怎么刷新。回执**一次性**：发一条就作废，\n#: 第二条必须重新 choose，否则 `tier_unconfirmed`（deepseek/gemini 都实测到）。\n#: gemini 的 choose 不认 `--think`（文档写着"当前未实现"），只能重设模型；\n#: review 要最高档，gemini 的档位序是 flash_lite→flash→pro→argon。\nTIER_RECIPE = {"gemini": ("--model", "argon"), "deepseek": ("--think", None)}\n\n\ndef _refresh_tier(site: str) -> None:\n    """写一条新的档位回执。不支持的端直接跳过（它们不校验回执）。"""\n    import subprocess\n\n    script = ROOT / "src" / "scripts" / f"{site}.py"\n    if not script.is_file() or site not in TIER_RECIPE:\n        return\n    flag, value = TIER_RECIPE[site]\n    if value is None:                     # deepseek：先关再开，否则"已是 on"不写回执\n        rounds = [("--think", "off"), ("--think", "on")]\n    else:\n        rounds = [(flag, value)]\n    for key, val in rounds:\n        try:\n            subprocess.run([sys.executable, str(script), "choose", key, val],\n                           cwd=ROOT, capture_output=True, text=True,\n                           encoding="utf-8", timeout=180)\n        except Exception:                 # noqa: BLE001\n            pass\n\n\ndef _ask_via_script(site: str, prompt: str, material_text: str, cfg,\n                    state=None) -> dict:\n    """走各端自己的 `*_use.py`（它们管新会话、档位、粘贴保真）。\n\n    为什么不自己拼 `flow.ask`：deepseek 的 review 档位回执由 **use 脚本**内部\n    `tier_guard.gate` 处理，`*_choose.py` 只认 `--think/--search`，接不上。\n\n    续跑：每段有固定身份（`chunk:<sha>`），已 `sent` 的跳过；`sending` 是\n    "上次发送途中被杀"，先对着页面核对这一段在不在，在就记账跳过、不在才补发。\n    """\n    import subprocess\n\n    script = ROOT / "src" / "scripts" / f"{site}.py"\n    limit = int((cfg.get("chunk_chars_by_site") or {}).get(site, cfg["chunk_chars"]))\n    chunks = it.pack_chunks_with_ids(material_text, limit, head=prompt, site=site)\n    total = len(chunks)\n    if chunks:\n        _clear_composer(_screen_for(site), site)      # 残草会让脚本直接拒发\n    pending = it.resume_chunks(chunks, state)\n    skipped = total - len(pending)\n    if chunks and not pending:\n        text = read_answer_text(_screen_for(site), site, prompt)\n        return {"ok": bool(text), "stage": "resumed_read" if text else "needs_manual_clear",\n                "reply": text, "feed": "paste", "chunks": total,\n                "resumed_skip": skipped}\n\n    last = {"ok": False, "stage": "no_chunks"}\n    for chunk in pending:\n        index, body = chunk["index"], chunk["text"]\n        record = state.chunk(chunk["id"]) if state is not None else {}\n        if record.get("status") == "sending":\n            # 上次发送途中被杀：只核对，不盲目重发。\n            if _page_has(_screen_for(site), site, f"第 {index}/{total} 段"):\n                state.mark_chunk(chunk["id"], "sent", reconciled=True)\n                continue\n        _refresh_tier(site)              # 档位回执是一次性的：每段都要重拿\n        budget = _review_budget(cfg) if index == total else int(\n            cfg.get("chunk_timeout", 300))\n        cmd = [sys.executable, str(script), "use", body, "--purpose", "review",\n               "--timeout", str(int(budget))]\n        if index > 1:\n            cmd.append("--continue")\n        if state is not None:\n            state.mark_chunk(chunk["id"], "sending")\n        proc, timeout_err = _run_or_timeout(\n            cmd, budget + 120, f"{site} 第 {index}/{total} 段")\n        if timeout_err:\n            return {**timeout_err, "feed": "paste", "chunks": total, "at": index}\n        parsed = None\n        for line in reversed((proc.stdout or "").splitlines()):\n            line = line.strip()\n            if line.startswith("{") and line.endswith("}"):\n                try:\n                    parsed = json.loads(line)\n                    break\n                except ValueError:\n                    continue\n        last = parsed or {"ok": False, "stage": "bad_output", "exit": proc.returncode}\n        if state is not None:\n            state.mark_chunk(chunk["id"], "sent" if last.get("ok") else "unknown",\n                             chars=len(last.get("reply") or ""))\n        if not last.get("ok"):\n            return {**last, "feed": "paste", "chunks": total, "at": index,\n                    "resumed_skip": skipped, "stderr": (proc.stderr or "")[-300:]}\n    return {**last, "feed": "paste", "chunks": total, "resumed_skip": skipped}\n\n\ndef _ask_paste(site: str, prompt: str, material_text: str, cfg, state=None) -> dict:\n    """分段粘贴：优先走各端 `*_use.py`。"""\n    if (ROOT / "src" / "scripts" / f"{site}.py").is_file():\n        return _ask_via_script(site, prompt, material_text, cfg, state)\n    from qi import flow\n\n    site_obj = _site_object(site)\n    chosen = _choose_tier(site)\n    limit = int((cfg.get("chunk_chars_by_site") or {}).get(site, cfg["chunk_chars"]))\n    if site in (cfg.get("single_line_sites") or []):\n        # deepseek / grok 的输入框折叠换行，读回必然 input_mismatch。\n        material_text = material_text.replace("\\n", " ⏎ ")\n        prompt = prompt.replace("\\n", " ⏎ ")\n    chunks = it.pack_chunks(material_text, limit, head=prompt)\n    last = {"ok": False, "stage": "no_chunks"}\n    if chunks:\n        _clear_composer(_screen_for(site), site)      # 上一轮残草会判 draft_present\n    for index, chunk in enumerate(chunks, start=1):\n        budget = _review_budget(cfg) if index == len(chunks) else int(\n            cfg.get("chunk_timeout", 300))\n        last = flow.ask(site_obj, chunk, mode=("new" if index == 1 else "continue"),\n                        timeout=budget, purpose="review", verbose=False)\n        if not last.get("ok"):\n            return {**last, "feed": "paste", "chunks": len(chunks), "at": index}\n    return {**last, "feed": "paste", "chunks": len(chunks), "choose": chosen}\n\n\ndef cmd_review(args, cfg) -> int:\n    state = it.State.load(ROOT, args.round)\n    _clear_stale_lock(state)             # 续跑前先处理上一条命令的死进程残留\n    done = state.done(f"review:{args.site}")\n    if done and not args.force:\n        print(json.dumps({"skipped": "already_done", **done}, ensure_ascii=False))\n        return 0\n\n    prompt_path = round_dir(args.round) / "prompt.md"\n    if not prompt_path.is_file():\n        print(json.dumps({"ok": False, "error": "prompt_missing",\n                          "hint": f"先写 {prompt_path}"}, ensure_ascii=False))\n        return 2\n    prompt = prompt_path.read_text(encoding="utf-8")\n    material = round_dir(args.round) / "materials" / "material.md"\n    mode = str(cfg["feed"].get(args.site, "paste"))\n\n    started = time.time()\n    if mode in ("upload", "upload-script"):\n        if not material.is_file():\n            print(json.dumps({"ok": False, "error": "material_missing"}, ensure_ascii=False))\n            return 2\n        ask = _ask_upload_script if mode == "upload-script" else _ask_upload\n        result = ask(args.site, prompt, material, cfg, state)\n    else:\n        text = material.read_text(encoding="utf-8") if material.is_file() else ""\n        result = _ask_paste(args.site, prompt, text, cfg, state)\n\n    reply = result.get("reply") or ""\n    replies_dir = round_dir(args.round) / "replies"\n    replies_dir.mkdir(parents=True, exist_ok=True)\n    (replies_dir / f"{args.site}.md").write_text(reply, encoding="utf-8")\n    payload = {"ok": bool(result.get("ok")), "stage": result.get("stage"),\n               "feed": result.get("feed", mode), "chars": len(reply),\n               "elapsed": round(time.time() - started, 1)}\n    state.mark(f"review:{args.site}", payload)\n    print(json.dumps(payload, ensure_ascii=False))\n\n    # 材料上传/粘贴的原始证据留档（不入库）\n    evidence = ROOT / "evidence" / "iterations" / args.round\n    evidence.mkdir(parents=True, exist_ok=True)\n    (evidence / f"{args.site}.json").write_text(\n        json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")\n    return 0 if result.get("ok") else 1\n\n\n# ---------------------------------------------------------------- 3. 验真\ndef _tree_paths(sha: str, rdir: Path | None = None) -> list:\n    """真值表：优先读本轮的 `tree.txt`（离线可测），否则问 git。"""\n    if rdir is not None:\n        cached = rdir / "tree.txt"\n        if cached.is_file():\n            return [line.strip() for line in cached.read_text(encoding="utf-8").splitlines()\n                    if line.strip()]\n    try:\n        out = git("ls-tree", "-r", "--name-only", sha)\n    except Exception:                    # noqa: BLE001 - 离线测试守卫会拦 subprocess\n        return []\n    return [line for line in out.splitlines() if line.strip()]\n\n\ndef cmd_verify(args, cfg) -> int:\n    state = it.State.load(ROOT, args.round)\n    snapshot = state.data.get("snapshot") or {}\n    sha = str(snapshot.get("sha") or "")\n    if not sha:\n        cached = round_dir(args.round) / "tree.txt"\n        if cached.is_file():\n            sha = "unknown"              # 有真值表就够，不必惊动 git（离线干跑）\n        else:\n            try:\n                sha = git("rev-parse", "HEAD")\n            except Exception:            # noqa: BLE001 - 没有 git 也能降级\n                sha = "unknown"\n    tree = _tree_paths(sha, round_dir(args.round))\n    spec_text = (ROOT / it.SPEC_PATH).read_text(encoding="utf-8")\n    # 本轮材料（Round 1 起含架构与已知问题）也算"可引用的正文"；\n    # 但"核心命中"仍只认规格本身。\n    material_path = round_dir(args.round) / "materials" / "material.md"\n    corpus = spec_text + ("\\n\\n" + material_path.read_text(encoding="utf-8")\n                          if material_path.is_file() else "")\n\n    replies_dir = round_dir(args.round) / "replies"\n    verdicts, report = {}, {}\n    for path in sorted(replies_dir.glob("*.md")):\n        site = path.stem\n        text = path.read_text(encoding="utf-8")\n        if "NO_ACCESS" in text[:200]:\n            verdict = {"hits": 0, "total": 0, "rate": 0.0, "core": False,\n                       "verdict": "no_access", "rows": []}\n        else:\n            verdict = it.verify_reply(text, tree_paths=tree, spec_text=corpus,\n                                      core_text=spec_text,\n                                      core_paths=(it.SPEC_PATH,))\n        verdicts[site] = verdict\n        report[site] = {"chars": len(text), **{k: verdict[k] for k in\n                                              ("hits", "total", "rate", "core", "verdict")}}\n\n    valid = [s for s, v in verdicts.items() if v["verdict"] == "true_read"]\n    summary = {"sha": sha, "valid_seats": valid, "valid_count": len(valid),\n               "meets_three_vendors": len(valid) >= 3, "seats": report}\n\n    it.write_archive(round_dir(args.round), {\n        "quote_check.json": {"summary": summary, "detail": verdicts},\n        "quote_check.md": _quote_md(summary, report),\n    })\n    state.mark("verify", {"valid": valid, "count": len(valid)})\n    print(json.dumps(summary, ensure_ascii=False, indent=2))\n    return 0 if summary["meets_three_vendors"] else 1\n\n\ndef _quote_md(summary, report) -> str:\n    lines = ["# 引用验真（Round 0 变体）", "",\n             f"快照 SHA：`{summary[\'sha\']}`", "",\n             "| 端 | 字数 | 命中 | 总数 | 命中率 | 核心命中 | 判定 |",\n             "|---|---:|---:|---:|---:|---|---|"]\n    for site, row in sorted(report.items()):\n        lines.append(f"| {site} | {row[\'chars\']} | {row[\'hits\']} | {row[\'total\']} | "\n                     f"{row[\'rate\']} | {\'是\' if row[\'core\'] else \'否\'} | {row[\'verdict\']} |")\n    lines += ["", f"有效（真读）：{\', \'.join(summary[\'valid_seats\']) or \'无\'}；"\n                  f"门槛 3 家：{\'满足\' if summary[\'meets_three_vendors\'] else \'未满足\'}"]\n    return "\\n".join(lines)\n\n\n# ---------------------------------------------------------------- 4. 匿名 + 5. 汇总\ndef cmd_anonymize(args, cfg) -> int:\n    state = it.State.load(ROOT, args.round)\n    qc = json.loads((round_dir(args.round) / "quote_check.json").read_text(encoding="utf-8"))\n    detail = qc["detail"]\n    replies = {p.stem: p.read_text(encoding="utf-8")\n               for p in sorted((round_dir(args.round) / "replies").glob("*.md"))}\n    pack = it.anonymize(replies, verdicts=detail)\n    (round_dir(args.round) / "anonymous_pack.md").write_text(pack, encoding="utf-8")\n    state.mark("anonymize", {"entries": pack.count("## F")})\n    print(json.dumps({"ok": True, "entries": pack.count("## F"),\n                      "chars": len(pack)}, ensure_ascii=False))\n    return 0\n\n\ndef _summarize_via_site(args, cfg, state, site: str) -> int:\n    """用非 Gemini 的端做汇总（附件 + 短指令），并归档会话 id 与汇总方。"""\n    pack_file = round_dir(args.round) / "anonymous_pack.md"\n    ask = str((cfg.get("summary_prompt_by_site") or {}).get(site)\n              or cfg.get("summary_prompt")\n              or "附件是匿名审查意见。请按四点汇总：1) 按主题聚类并注明合并了哪几条；"\n                 "2) 标出冲突；3) 按对本项目的好处排序；4) 你要补充的新缺陷单独列在「汇总者新增」。"\n                 "不要猜来源，1500 字内。")\n    local = dict(cfg)\n    local.pop("upload_prompt", None)\n    local["upload_prompt_by_site"] = {}\n    result = _ask_upload(site, ask, pack_file, local, state, force_new=True)\n    reply = result.get("reply") or ""\n    url = _url_now(_screen_for(site), site)\n    session_id = conversation_session_id(url) if url else None\n    payload = {"summarizer": site, "session_id": session_id, "url": url,\n               "chars": len(reply), "stage": result.get("stage"),\n               "at": time.strftime("%Y-%m-%dT%H:%M:%S%z")}\n    (round_dir(args.round) / "gemini_summary.json").write_text(\n        json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")\n    (round_dir(args.round) / "gemini_summary.md").write_text(reply, encoding="utf-8")\n    state.mark("summarize", {"chars": len(reply), "session_id": session_id,\n                             "summarizer": site})\n    if not result.get("ok") or session_id is None:\n        print(json.dumps({"ok": False, "stage": result.get("stage") or "summary_not_isolated",\n                          "summarizer": site, "session_id": session_id,\n                          "chars": len(reply)}, ensure_ascii=False))\n        return 1\n    print(json.dumps({"ok": True, "summarizer": site, "chars": len(reply),\n                      "session_id": session_id}, ensure_ascii=False))\n    return 0\n\n\ndef cmd_summarize(args, cfg) -> int:\n    """匿名包 → Gemini 汇总。**必须先开新对话**，并把会话 ID 记进归档。\n\n    为什么必须新开：汇总者与四审里都有 gemini，同一个会话等于让它"认出自己"，\n    匿名就白做了（规格 §9.2，chatgpt/grok 都点过这条）。\n    会话 ID 是"确实换了会话"的唯一客观证据——只写"我开了新对话"不算。\n    """\n    from qi import conversation, ui, uilock\n\n    state = it.State.load(ROOT, args.round)\n    _clear_stale_lock(state)\n    site = (getattr(args, "site", None) or "gemini").strip().lower()\n    if site != "gemini":\n        # 换汇总方（规格默认 Gemini）。gemini 拒答时的退路：同样必须新开对话、\n        # 同样把会话 id 写进归档，只把"谁来汇总"如实记下来。\n        return _summarize_via_site(args, cfg, state, site)\n    pack = (round_dir(args.round) / "anonymous_pack.md").read_text(encoding="utf-8")\n    prompt = it.anonymize_prompt(pack)\n    screen = _screen_for("gemini")\n    _clear_composer(screen, "gemini")\n    if str(cfg.get("summary_via") or "") == "upload":\n        # 匿名包动辄上万字，gemini 的输入框塞不下（实测 input_mismatch）。\n        # 改走附件 + 一条短指令；前提仍是**先新开对话**。\n        from qi import upload as upload_mod\n\n        pack_file = round_dir(args.round) / "anonymous_pack.md"\n        with uilock.hold("iterate:summarize:gemini",\n                         timeout=float(cfg.get("ui_lock_timeout", 180))):\n            if not start_new_chat(screen, "gemini"):\n                print(json.dumps({"ok": False, "stage": "new_chat_failed",\n                                  "hint": "汇总必须新开对话；没开成就不发"},\n                                 ensure_ascii=False))\n                return 1\n            up = upload_mod.upload(screen, "gemini", str(pack_file),\n                                   timeout=cfg["upload_timeout"])\n            if not up.ok:\n                print(json.dumps({"ok": False, "stage": "upload_failed",\n                                  **up.as_dict()}, ensure_ascii=False))\n                return 1\n            _upload_settled("gemini", screen)\n        _refresh_tier("gemini")\n        short = str(cfg.get("summary_prompt") or\n                    "附件是匿名审查意见。请按四点汇总：1) 按主题聚类并注明合并了哪几条；"\n                    "2) 标出冲突；3) 按对本项目的好处排序；4) 你要补充的新缺陷单独列在「汇总者新增」。"\n                    "不要猜来源，1500 字内。")\n        script = ROOT / "src" / "scripts" / "gemini.py"\n        budget = _review_budget(cfg)\n        proc, timeout_err = _run_or_timeout(\n            [sys.executable, str(script), "use", short, "--purpose", "review",\n             "--continue", "--timeout", str(budget)],\n            budget + 180, "gemini 汇总")\n        if timeout_err:\n            print(json.dumps({**timeout_err, "summarizer": "gemini"},\n                             ensure_ascii=False))\n            return 1\n        parsed = None\n        for line in reversed((proc.stdout or "").splitlines()):\n            line = line.strip()\n            if line.startswith("{") and line.endswith("}"):\n                try:\n                    parsed = json.loads(line)\n                    break\n                except ValueError:\n                    continue\n        result = dict(parsed or {"ok": False, "stage": "bad_output",\n                                 "exit": proc.returncode})\n    else:\n        with uilock.hold("iterate:summarize:gemini",\n                         timeout=float(cfg.get("ui_lock_timeout", 180))):\n            if not start_new_chat(screen, "gemini"):\n                print(json.dumps({"ok": False, "stage": "new_chat_failed",\n                                  "hint": "汇总必须新开对话；没开成就不发"},\n                                 ensure_ascii=False))\n                return 1\n            _refresh_tier("gemini")          # 回执一次性\n            conv = _conversation(screen, "gemini")\n            result = conversation.ask(conv, prompt, timeout=_review_budget(cfg),\n                                      purpose="review")\n\n    url = ""\n    try:\n        _control, url = ui.document(screen.target_hwnd, "gemini")\n    except Exception:                     # noqa: BLE001 - 读不到就记 None，由判定兜底\n        pass\n    session_id = conversation_session_id(url) if url else None\n    reply = result.get("reply") or ""\n    payload = {"session_id": session_id, "url": url, "chars": len(reply),\n               "stage": result.get("stage"), "at": time.strftime("%Y-%m-%dT%H:%M:%S%z")}\n    (round_dir(args.round) / "gemini_summary.json").write_text(\n        json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")\n    (round_dir(args.round) / "gemini_summary.md").write_text(reply, encoding="utf-8")\n    state.mark("summarize", {"chars": len(reply), "session_id": session_id})\n\n    if not result.get("ok"):\n        print(json.dumps({"ok": False, "stage": result.get("stage"),\n                          "session_id": session_id}, ensure_ascii=False))\n        return 1\n    if session_id is None:\n        # 页面没带会话 id = 没有真正进入新会话，汇总结果不可信。\n        print(json.dumps({"ok": False, "stage": "summary_not_isolated",\n                          "session_id": None, "chars": len(reply)}, ensure_ascii=False))\n        return 1\n    print(json.dumps({"ok": True, "chars": len(reply), "session_id": session_id},\n                     ensure_ascii=False))\n    return 0\n\n\n# ---------------------------------------------------------------- 上传自检\ndef cmd_upload_check(args, cfg) -> int:\n    """新会话 → 上传一个小文件 → 只问一句 → 答案必须来自文件内容。\n\n    规格 §8 要求「文件已落到该端、对方按文件内容作答」，这一步就是那个自检。\n    """\n    from qi import conversation, upload\n\n    site = args.site or "chatgpt"\n    sample = ROOT / "docs" / "iterations" / args.round / "materials" / "upload_check.md"\n    sample.parent.mkdir(parents=True, exist_ok=True)\n    token = "BRIDGE-UPLOAD-CHECK-20261111"\n    sample.write_text(f"# 上传自检\\n\\n本文件只有一行关键内容：{token}\\n", encoding="utf-8")\n\n    screen = _screen_for(site, new=True)\n    if not start_new_chat(screen, site):\n        print(json.dumps({"ok": False, "stage": "new_chat_failed"}, ensure_ascii=False))\n        return 1\n    _clear_composer(screen, site)\n    up = upload.upload(screen, site, str(sample), timeout=cfg["upload_timeout"])\n    if not up.ok:\n        print(json.dumps({"ok": False, "stage": "upload_failed", **up.as_dict()},\n                         ensure_ascii=False))\n        return 1\n    _upload_settled(site, screen)\n    conv = _conversation(screen, site)\n    result = conversation.ask(conv, "附件里那行关键内容是什么？只回答那一行，不要解释。",\n                              timeout=_review_budget(cfg), purpose="review")\n    reply = (result.get("reply") or "").strip()\n    ok = token.lower() in reply.lower()\n    payload = {"ok": bool(result.get("ok")) and ok, "upload": up.as_dict(),\n               "stage": result.get("stage"), "answer": reply[:200],\n               "token_found": ok}\n    (ROOT / "docs" / "iterations" / args.round / "upload_check.json").write_text(\n        json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")\n    print(json.dumps(payload, ensure_ascii=False))\n    return 0 if payload["ok"] else 1\n\n\n# ---------------------------------------------------------------- status\ndef cmd_status(args, cfg) -> int:\n    state = it.State.load(ROOT, args.round)\n    print(json.dumps(state.data, ensure_ascii=False, indent=2))\n    return 0\n\n\ndef main(argv=None) -> int:\n    parser = argparse.ArgumentParser(description="自迭代循环驱动器")\n    parser.add_argument("command", choices=("status", "snapshot", "review", "verify",\n                                            "anonymize", "summarize", "upload-check"))\n    parser.add_argument("--round", default="round-0")\n    parser.add_argument("--site", default=None)\n    parser.add_argument("--force", action="store_true")\n    args = parser.parse_args(argv)\n    cfg = load_config()\n    if args.command == "review" and not args.site:\n        parser.error("review 需要 --site")\n    return {"status": cmd_status, "snapshot": cmd_snapshot, "review": cmd_review,\n            "verify": cmd_verify, "anonymize": cmd_anonymize,\n            "summarize": cmd_summarize, "upload-check": cmd_upload_check}[args.command](args, cfg)\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n',
}

_LOADED_MODS: dict[str, types.ModuleType] = {}


def _strip_main_block(src: str) -> str:
    for marker in ('if __name__ == "__main__":', "if __name__ == '__main__':"):
        idx = src.rfind(marker)
        if idx != -1:
            return src[:idx]
    return src


def get_subcommand_module(name: str, force_reload: bool = False) -> types.ModuleType:
    if name not in _LOADED_MODS or force_reload:
        mod = _LOADED_MODS.get(name) or types.ModuleType(f"scripts.{name}")
        mod.__file__ = __file__
        mod.__package__ = __package__ or "scripts"
        # Python 3.10 下 from __future__ import annotations + @dataclass 会经
        # sys.modules 查 cls.__module__；exec 前必须先注册。
        sys.modules[mod.__name__] = mod
        exec(compile(_strip_main_block(_SUBMODULES_SRC[name]), __file__, "exec"), mod.__dict__)
        _LOADED_MODS[name] = mod
    return _LOADED_MODS[name]


def __getattr__(attr: str):
    """向后兼容原 bridge_server.py 的顶层函数与常量导入。"""
    m = get_subcommand_module("bridge_server")
    if hasattr(m, attr):
        return getattr(m, attr)
    raise AttributeError(f"module {__name__!r} has no attribute {attr!r}")


def _invoke_module_main(mod_name: str, argv: list[str]) -> int:
    mod = get_subcommand_module(mod_name)
    fn = mod.main
    saved = sys.argv[:]
    try:
        sys.argv = [f"{sys.argv[0]} {mod_name}"] + argv
        sig = inspect.signature(fn)
        if len(sig.parameters) > 0:
            return int(fn(argv))
        return int(fn())
    finally:
        sys.argv = saved


def _handle_run(argv: list[str]) -> int:
    if not argv or argv[0] in ("-h", "--help"):
        print("用法: python src/scripts/bridge.py run <chatgpt|gemini|grok|deepseek|codex|dsh|opencode|workbuddy> [choose|use] [参数...]")
        return 0 if argv else 2
    ai_name = argv[0]
    ai_script = ROOT / "src" / "scripts" / f"{ai_name}.py"
    if not ai_script.exists():
        print(f"未知 AI 端点: {ai_name} (未找到 {ai_script})", file=sys.stderr)
        return 2
    return subprocess.call([sys.executable, str(ai_script)] + argv[1:])


def _handle_tools(argv: list[str]) -> int:
    """本地诊断工具入口（落实 Grok 审查建议第 6 条：方便调用本地保留的 tools/*.py）。"""
    tools_dir = ROOT / "tools"
    available = sorted(p.stem for p in tools_dir.glob("*.py")) if tools_dir.exists() else []
    if not argv or argv[0] in ("-l", "--list", "-h", "--help"):
        print("可用本地诊断工具 (位于本地 tools/ 目录):")
        for t in available:
            print(f"  - {t}  (运行: python src/scripts/bridge.py tools {t} [参数...])")
        return 0
    tool_name = argv[0].removesuffix(".py")
    tool_path = tools_dir / f"{tool_name}.py"
    if not tool_path.exists():
        print(f"未找到本地诊断脚本: {tool_path}", file=sys.stderr)
        return 2
    return subprocess.call([sys.executable, str(tool_path)] + argv[1:])


def build_parser() -> argparse.ArgumentParser:
    ap = argparse.ArgumentParser(
        prog="bridge.py",
        description="Bridge 唯一总控入口（服务管理 / 8端调度 / 派单 / 自迭代 / 工作流 / 通知 / 本地诊断）",
    )
    sub = ap.add_subparsers(dest="subcommand", metavar="<command>")
    sub.add_parser("start", add_help=False, help="启动本地 127.0.0.1:18765 HTTP 服务 (--fg 前台运行)")
    sub.add_parser("stop", add_help=False, help="停止本地 HTTP 服务 (--force 强杀)")
    sub.add_parser("status", add_help=False, help="查询本地 HTTP 服务健康状态")
    sub.add_parser("rotate", add_help=False, help="轮换本地鉴权 Token")
    sub.add_parser("run", add_help=False, help="直接运行指定 AI 独立脚本 (如 run chatgpt choose --list)")
    sub.add_parser("ask", add_help=False, help="向本地服务提交 /ask 多端任务并轮询终态")
    sub.add_parser("iterate", add_help=False, help="执行自迭代十步循环 (status / review / verify)")
    sub.add_parser("workflow", add_help=False, help="工作流状态机管理 (status / move / advance / resolve-hold)")
    sub.add_parser("notify", add_help=False, help="写入 progress.json 并发送完工通知")
    sub.add_parser("autopush", add_help=False, help="检测 WorkBuddy 空闲并自动补发继续指令")
    sub.add_parser("tools", add_help=False, help="调用本地保留的 tools/ 诊断工具 (如 verify_all / arch_stats)")
    return ap


def main(argv: list[str] | None = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    if not args:
        return _invoke_module_main("bridge_server", ["status"])

    if args[0] in ("-h", "--help"):
        build_parser().print_help()
        return 0

    cmd, rest = args[0], args[1:]
    if cmd in ("start", "stop", "status", "rotate"):
        return _invoke_module_main("bridge_server", args)
    if cmd == "server":
        return _invoke_module_main("bridge_server", rest)
    if cmd == "run":
        return _handle_run(rest)
    if cmd in ("ask", "job", "live-job"):
        return _invoke_module_main("live_job", rest)
    if cmd == "iterate":
        return _invoke_module_main("iterate", rest)
    if cmd == "workflow":
        return _invoke_module_main("workflow_use", rest)
    if cmd == "notify":
        return _invoke_module_main("notify_done", rest)
    if cmd == "autopush":
        return _invoke_module_main("workbuddy_autopush", rest)
    if cmd == "tools":
        return _handle_tools(rest)

    return _invoke_module_main("bridge_server", args)


if __name__ == "__main__":
    raise SystemExit(main())
